static const char *intckParseCreateIndex(const char *z, int iCol, int *pnByte){
  int iOff = 0;
  int iThisCol = 0;
  int iStart = 0;
  int nOpen = 0;
  const char *zRet = 0;
  int nRet = 0;
  int iEndOfCol = 0;
  while( z[iOff]!='(' ){
    iOff += intckGetToken(&z[iOff]);
    if( z[iOff]=='\0' ) return 0;
  }
  assert( z[iOff]=='(' );
  nOpen = 1;
  iOff++;
  iStart = iOff;
  while( z[iOff] ){
    const char *zToken = &z[iOff];
    int nToken = 0;
    if( nOpen==1 ){
      if( z[iOff]==',' || z[iOff]==')' ){
        if( iCol==iThisCol ){
          int iEnd = iEndOfCol ? iEndOfCol : iOff;
          nRet = (iEnd - iStart);
          zRet = &z[iStart];
          break;
        }
        iStart = iOff+1;
        while( intckIsSpace(z[iStart]) ) iStart++;
        iThisCol++;
      }
      if( z[iOff]==')' ) break;
    }
    if( z[iOff]=='(' ) nOpen++;
    if( z[iOff]==')' ) nOpen--;
    nToken = intckGetToken(zToken);
    if( (nToken==3 || 0==sqlite3_strnicmp(zToken, "ASC", nToken))
     || (nToken==4 && 0==sqlite3_strnicmp(zToken, "DESC", nToken))
    ){
      iEndOfCol = iOff;
    }else if( 0==intckIsSpace(zToken[0]) ){
      iEndOfCol = 0;
    }
    iOff += nToken;
  }
  while( zRet==0 && z[iOff] ){
    int n = intckGetToken(&z[iOff]);
    if( n==5 && 0==sqlite3_strnicmp(&z[iOff], "where", 5) ){
      zRet = &z[iOff+5];
      nRet = (int)strlen(zRet);
    }
    iOff += n;
  }
  if( zRet ){
    while( intckIsSpace(zRet[0]) ){
      nRet--;
      zRet++;
    }
    while( nRet>0 && intckIsSpace(zRet[nRet-1]) ) nRet--;
  }
  *pnByte = nRet;
  return zRet;
}

static int8_t self_test_entry_config(struct bmm350_dev *dev)
{
    int8_t rslt;
    uint8_t cmd;
    struct bmm350_pmu_cmd_status_0 pmu_cmd_stat_0 = { 0 };
    cmd = BMM350_PMU_CMD_SUS;
    rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &cmd, 1, dev);
    if (rslt == BMM350_OK) {
        rslt = bmm350_delay_us(30000, dev);
    }
    if (rslt == BMM350_OK) {
        rslt = bmm350_set_odr_performance(BMM350_DATA_RATE_100HZ, BMM350_AVERAGING_2, dev);
        if (rslt == BMM350_OK) {
            rslt = bmm350_enable_axes(BMM350_X_EN, BMM350_Y_EN, BMM350_Z_EN, dev);
        }
    }
    cmd = BMM350_PMU_CMD_FGR;
    if (rslt == BMM350_OK) {
        rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &cmd, 1, dev);
        if (rslt == BMM350_OK) {
            rslt = bmm350_delay_us(30000, dev);
        }
    }
    if (rslt == BMM350_OK) {
        rslt = bmm350_get_pmu_cmd_status_0(&pmu_cmd_stat_0, dev);
        if ((rslt == BMM350_OK) && (pmu_cmd_stat_0.pmu_cmd_value == BMM350_PMU_CMD_STATUS_0_FGR)) {
            cmd = BMM350_PMU_CMD_BR_FAST;
            rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &cmd, 1, dev);
            if (rslt == BMM350_OK) {
                rslt = bmm350_delay_us(4000, dev);
            }
        }
    }
    if (rslt == BMM350_OK) {
        rslt = bmm350_get_pmu_cmd_status_0(&pmu_cmd_stat_0, dev);
    }
    if ((rslt == BMM350_OK) && (pmu_cmd_stat_0.pmu_cmd_value == BMM350_PMU_CMD_STATUS_0_BR_FAST)) {
        cmd = BMM350_PMU_CMD_FM_FAST;
        rslt = bmm350_set_regs(BMM350_REG_PMU_CMD, &cmd, 1, dev);
        if (rslt == BMM350_OK) {
            rslt = bmm350_delay_us(16000, dev);
        }
        if (rslt == BMM350_OK) {
            rslt = bmm350_get_pmu_cmd_status_0(&pmu_cmd_stat_0, dev);
            if ((rslt == BMM350_OK) && (pmu_cmd_stat_0.pmu_cmd_value == BMM350_PMU_CMD_STATUS_0_FM_FAST)) {
                rslt = bmm350_delay_us(10, dev);
            }
        }
    }
    return rslt;
}

