static uint8_t out_db_to_percent(float db)
{
    if (db <= -96.0f) {
        return 0;
    }
    if (db >= 0.0f) {
        return 100;
    }
    if (db <= -49.5f) {
        return 1;
    }
    return clamp_percent((int)lroundf(100.0f + db * 2.0f));
}

