                    message,
                    "Are you sure you\nwant to delete\nthis file?",
                    50,
                    14,
                    AlignLeft,
                    AlignTop);
                DialogMessageButton dialog_result = dialog_message_show(app->dialogs, message);
                dialog_message_free(message);
                furi_record_close(RECORD_DIALOGS);
