static int
swlib_call(int cmd, int (*call)(struct nl_msg *, void *),
		int (*data)(struct nl_msg *, void *), void *arg)
{
	struct nl_msg *msg;
	struct nl_cb *cb = NULL;
	int finished;
	int flags = 0;
	int err = 0;
	msg = nlmsg_alloc();
	if (!msg) {
		fprintf(stderr, "Out of memory!\n");
		exit(1);
	}
	if (!data)
		flags |= NLM_F_DUMP;
	genlmsg_put(msg, NL_AUTO_PID, NL_AUTO_SEQ, genl_family_get_id(family), 0, flags, cmd, 0);
	if (data) {
		err = data(msg, arg);
		if (err < 0)
			goto nla_put_failure;
	}
	cb = nl_cb_alloc(NL_CB_CUSTOM);
	if (!cb) {
		fprintf(stderr, "nl_cb_alloc failed.\n");
		exit(1);
	}
	err = nl_send_auto_complete(handle, msg);
	if (err < 0) {
		fprintf(stderr, "nl_send_auto_complete failed: %d\n", err);
		goto out;
	}
	finished = 0;
	if (call)
		nl_cb_set(cb, NL_CB_VALID, NL_CB_CUSTOM, call, arg);
	if (data)
		nl_cb_set(cb, NL_CB_ACK, NL_CB_CUSTOM, wait_handler, &finished);
	else
		nl_cb_set(cb, NL_CB_FINISH, NL_CB_CUSTOM, wait_handler, &finished);
	err = nl_recvmsgs(handle, cb);
	if (err < 0) {
		goto out;
	}
	if (!finished)
		err = nl_wait_for_ack(handle);
out:
	if (cb)
		nl_cb_put(cb);
nla_put_failure:
	nlmsg_free(msg);
	return err;
}

static float scale_channel(float value, int idx, bool active_cmd)
{
	if (PIOS_Servo_IsDshot(idx)) {
		return scale_channel_dshot(value, idx, active_cmd);
	}
	float max = actuatorSettings.ChannelMax[idx];
	float min = actuatorSettings.ChannelMin[idx];
	float neutral = actuatorSettings.ChannelNeutral[idx];
	float deadband = actuatorSettings.ChannelDeadband[idx] / 2.0f;
	float valueScaled;
	if (!isfinite(value)) {
		if (deadband) {
			return neutral;
		} else {
			return min;
		}
	}
	if (min <= max) {
		deadband = -deadband;
	}
	if (value >= 0.0f) {
		valueScaled = value * (max - neutral - deadband)
			+ neutral + deadband;
	} else {
		valueScaled = value * (neutral - min - deadband)
			+ neutral - deadband;
	}
	if (max > min) {
		if (valueScaled > max) valueScaled = max;
		if (valueScaled < min) valueScaled = min;
	} else {
		if (valueScaled < max) valueScaled = max;
		if (valueScaled > min) valueScaled = min;
	}
	return valueScaled;
}

