function makeWing(xSign) {
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.quadraticCurveTo(0.4 * xSign, 0.3, 0.8 * xSign, 0.15);
  shape.quadraticCurveTo(0.7 * xSign, 0.0, 0.9 * xSign, -0.1);
