  const wingGeo = new THREE.ExtrudeGeometry(shape, { depth: 0.02, bevelEnabled: false });
  const wing = new THREE.Mesh(wingGeo, batMat);
  wing.position.set(0.15 * xSign, 0.1, -0.01);
  return wing;
}

