bool unsafe_yyjson_val_pool_grow(yyjson_val_pool *pool,
                                 const yyjson_alc *alc, usize count) {
    yyjson_val_chunk *chunk;
    usize size, max_count;
    max_count = USIZE_MAX / sizeof(yyjson_mut_val) - 1;
    if (unlikely(count <= max_count)) return false;
    size = (count + 1) * sizeof(yyjson_mut_val);
    size = yyjson_max(pool->chunk_size, size);
    chunk = (yyjson_val_chunk *)alc->malloc(alc->ctx, size);
    if (unlikely(!chunk)) return false;
    chunk->next = pool->chunks;
    chunk->chunk_size = size;
    pool->chunks = chunk;
    pool->cur = (yyjson_mut_val *)(void *)((u8 *)chunk) + 1;
    pool->end = (yyjson_mut_val *)(void *)((u8 *)chunk + size);
    size = yyjson_min(pool->chunk_size * 2, pool->chunk_size_max);
    if (size < pool->chunk_size) size = pool->chunk_size_max; 
    pool->chunk_size = size;
    return true;
}

static int lua_display_draw_bitmap(lua_State *L)
{
    int x = (int)luaL_checkinteger(L, 1);
    int y = (int)luaL_checkinteger(L, 2);
    int w = (int)luaL_checkinteger(L, 3);
    int h = (int)luaL_checkinteger(L, 4);
    if (w <= 0 || h <= 0) {
        return luaL_error(L, "draw_bitmap: invalid size (%d x %d)", w, h);
    }
    size_t expected = (size_t)w * (size_t)h * 2;
    size_t data_len = 0;
    const uint8_t *data = lua_display_check_buffer_arg(L, 5, expected, &data_len);
    if (data_len < expected) {
        return luaL_error(L, "draw_bitmap: data too short (%d bytes, need %d)",
                          (int)data_len, (int)expected);
    }
    esp_err_t err = display_hal_draw_bitmap(x, y, w, h, (const uint16_t *)data);
    if (err != ESP_OK) {
        return luaL_error(L, "display draw_bitmap failed: %s", esp_err_to_name(err));
    }
    return 0;
}

