	hapd->dpp_pkex_code_len = os_strlen(hapd->dpp_pkex_code);
	pos = os_strstr(cmd, " ver=");
	if (pos) {
		int v;
		pos += 5;
		v = atoi(pos);
		if (v == 1)
			ver = PKEX_VER_ONLY_1;
		else if (v == 2)
			ver = PKEX_VER_ONLY_2;
		else
			return -1;
	}
