def _validate_parse_dates_presence(self, columns: Sequence[Hashable]) -> Iterable:




        cols_needed: Iterable
        if is_dict_like(self.parse_dates):
            cols_needed = itertools.chain(*self.parse_dates.values())
        elif is_list_like(self.parse_dates):
            # a column in parse_dates could be represented
            # ColReference = Union[int, str]
            # DateGroups = List[ColReference]
            # ParseDates = Union[DateGroups, List[DateGroups],
            #     Dict[ColReference, DateGroups]]
            cols_needed = itertools.chain.from_iterable(
                col if is_list_like(col) and not isinstance(col, tuple) else [col]
                for col in self.parse_dates
            )
        else:
            cols_needed = []

        cols_needed = list(cols_needed)

        # get only columns that are references using names (str), not by index
        missing_cols = ", ".join(
            sorted(
                {
                    col
                    for col in cols_needed
                    if isinstance(col, str) and col not in columns
                }
            )
        )
        if missing_cols:
            raise ValueError(
                f"Missing column provided to 'parse_dates': '{missing_cols}'"
            )
        # Convert positions to actual column names
        return [
            col if (isinstance(col, str) or col in columns) else columns[col]
            for col in cols_needed
        ]

int process_exec_args(const char *path, int argc, char **argv) {
  int pid = process_create(path, argc, argv);
  if (pid < 0) {
    return pid; 
  }
  process_start(pid);
  int slot = -1;
  for (int i = 0; i < MAX_PROCESSES; i++) {
    if (proc_table[i].pid == pid) {
      slot = i;
      break;
    }
  }
  if (slot < 0) {
    printf("[PROC] exec: process disappeared?\n");
    return -1;
  }
  while (proc_table[slot].state != PROC_STATE_FREE &&
         proc_table[slot].state != PROC_STATE_ZOMBIE) {
    process_schedule();
  }
  int result = proc_table[slot].exit_status;
  printf("[PROC] Process '%s' (pid %d) finished with status %d\n", path, pid,
         result);
  return result;
}

public Object answer(InvocationOnMock invocation) {
        if (methodsGuru.isToString(invocation.getMethod())) {
            Object mock = invocation.getMock();
            MockName name = mockUtil.getMockName(mock);
            if (name.isDefault()) {
                return "Mock for " + mockUtil.getMockSettings(mock).getTypeToMock().getSimpleName() + ", hashCode: " + mock.hashCode();
            } else {
                return name.toString();
            }
        } else if (methodsGuru.isCompareToMethod(invocation.getMethod())) {
            //see issue 184.
            //mocks by default should return 0 if references are the same, otherwise some other value because they are not the same. Hence we return 1 (anything but 0 is good).
            //Only for compareTo() method by the Comparable interface
            return 1;
        }

        Class<?> returnType = invocation.getMethod().getReturnType();
        return returnValueFor(returnType);
    }

static int32_t check_safe_to_arm()
{
	FlightStatusData flightStatus;
	FlightStatusGet(&flightStatus);
	if (flightStatus.Armed == FLIGHTSTATUS_ARMED_ARMED) {
		switch (flightStatus.FlightMode) {
			case FLIGHTSTATUS_FLIGHTMODE_MANUAL:
			case FLIGHTSTATUS_FLIGHTMODE_ACRO:
			case FLIGHTSTATUS_FLIGHTMODE_ACROPLUS:
			case FLIGHTSTATUS_FLIGHTMODE_ACRODYNE:
			case FLIGHTSTATUS_FLIGHTMODE_LEVELING:
			case FLIGHTSTATUS_FLIGHTMODE_HORIZON:
			case FLIGHTSTATUS_FLIGHTMODE_AXISLOCK:
			case FLIGHTSTATUS_FLIGHTMODE_VIRTUALBAR:
			case FLIGHTSTATUS_FLIGHTMODE_STABILIZED1:
			case FLIGHTSTATUS_FLIGHTMODE_STABILIZED2:
			case FLIGHTSTATUS_FLIGHTMODE_STABILIZED3:
			case FLIGHTSTATUS_FLIGHTMODE_ALTITUDEHOLD:
			case FLIGHTSTATUS_FLIGHTMODE_FLIPREVERSED:
				break;
			case FLIGHTSTATUS_FLIGHTMODE_LQG:
			case FLIGHTSTATUS_FLIGHTMODE_LQGLEVELING:
				if (!lqg_sysident_check()) {
					return SYSTEMALARMS_CONFIGERROR_LQG;
				}
				break;
			case FLIGHTSTATUS_FLIGHTMODE_FAILSAFE:
				break;
			default:
				return SYSTEMALARMS_CONFIGERROR_UNSAFETOARM;
		}
	}
	return SYSTEMALARMS_CONFIGERROR_NONE;
}

static irqreturn_t mailbox_irq_handler(int irq, void *dev_id)
{
    unsigned int isr;
    int i;
    isr = IFX_REG_R32(MBOX_IGU1_ISR);
    IFX_REG_W32(isr, MBOX_IGU1_ISRC);
    isr &= IFX_REG_R32(MBOX_IGU1_IER);
    while ( (i = __fls(isr)) >= 0 ) {
        isr ^= 1 << i;
        if ( i >= 16 ) {
            IFX_REG_W32_MASK(1 << i, 0, MBOX_IGU1_IER);
            i -= 16;
            if ( i < MAX_ITF_NUMBER )
                netif_wake_queue(g_net_dev[i]);
        }
        else {
#ifdef CONFIG_IFX_PTM_RX_INTERRUPT
            while ( WRX_DMA_CHANNEL_CONFIG(i)->vlddes > 0 )
                mailbox_rx_irq_handler(i);
#else
            IFX_REG_W32_MASK(1 << i, 0, MBOX_IGU1_IER);
            napi_schedule(&g_ptm_priv_data.itf[i].napi);
#endif
        }
    }
    return IRQ_HANDLED;
}

int es8311_audio_init(void *i2c_bus, int pa_pin)
{
    s_pa_pin = pa_pin;
    if (pa_pin >= 0) {
        gpio_config_t pa_cfg = {
            .pin_bit_mask = (1ULL << pa_pin),
            .mode = GPIO_MODE_OUTPUT,
            .pull_up_en = GPIO_PULLUP_DISABLE,
            .pull_down_en = GPIO_PULLDOWN_DISABLE,
            .intr_type = GPIO_INTR_DISABLE,
        };
        gpio_config(&pa_cfg);
        gpio_set_level(pa_pin, 0);
    }
    i2s_chan_handle_t tx_handle = NULL;
    i2s_chan_handle_t rx_handle = NULL;
    i2s_chan_config_t chan_cfg = I2S_CHANNEL_DEFAULT_CONFIG(
