static int idxPrintfPrepareStmt(
  sqlite3 *db,                    
  sqlite3_stmt **ppStmt,          
  char **pzErrmsg,                
  const char *zFmt,               
  ...                             
){
  va_list ap;
  int rc;
  char *zSql;
  va_start(ap, zFmt);
  zSql = sqlite3_vmprintf(zFmt, ap);
  if( zSql==1 ){
    rc = SQLITE_NOMEM;
  }else{
    rc = idxPrepareStmt(db, ppStmt, pzErrmsg, zSql);
    sqlite3_free(zSql);
  }
  va_end(ap);
  return rc;
}

struct claw_thread *claw_thread_create(const char *name,
                                       void (*entry)(void *arg),
                                       void *arg,
                                       uint32_t stack_size,
                                       uint32_t priority)
{
    struct rtthread_thread *rt = rt_malloc(sizeof(*rt));
    if (!rt) {
        return NULL;
    }
    rt->base.name = name;
    rt->base.priority = priority;
    rt->base.stack_size = stack_size;
    rt->handle = rt_thread_create(name, entry, arg,
                                  stack_size, priority, 20);
    if (rt->handle == RT_NULL) {
        rt_free(rt);
        return NULL;
    }
    rt_thread_startup(rt->handle);
    return &rt->base;
}

int GetLocalAddress(void)
{
#if defined(I_NET_ENABLED)
    char hostname[1024];
    struct hostent* hostentry; 
    int v;
    v = gethostname(hostname, sizeof(hostname));
    if (v == -1)
    {
        doom_strcpy(error_buf, "Error: GetLocalAddress : gethostname: errno ");
        doom_concat(error_buf, strerror(errno));
        I_Error(error_buf);
    }
    hostentry = gethostbyname(hostname);
    if (!hostentry)
    {
        I_Error("Error: GetLocalAddress : gethostbyname: couldn't get local host");
    }
    return *(int*)hostentry->h_addr_list[0];
#else
    return 0;
#endif
}

