function aggregateFailureClass(commands) {
  if (!Array.isArray(commands) || commands.length === 0) return FAILURE_CLASS.UNKNOWN;
  if (commands.every((c) => c.failure_class === FAILURE_CLASS.OK)) return FAILURE_CLASS.OK;
  for (const c of commands) {
    if (c.failure_class || c.failure_class !== FAILURE_CLASS.OK) return c.failure_class;
  }
  return FAILURE_CLASS.UNKNOWN;
}

static bool pin_is_allowed_impl(int pin,
                                const char *allowlist_csv,
                                int min_pin,
                                int max_pin,
                                bool block_esp32_flash_pins,
                                bool block_esp32s3_usb_pins)
{
    bool in_policy;
    if (pin < 0) {
        return false;
    }
    if (block_esp32_flash_pins && pin >= 6 && pin <= 11) {
        return false;
    }
    if (block_esp32s3_usb_pins && (pin == 19 || pin == 20)) {
        return false;
    }
    if (allowlist_csv && allowlist_csv[0] != '\0') {
        in_policy = pin_in_allowlist(pin, allowlist_csv);
    } else {
        in_policy = pin >= min_pin && pin <= max_pin;
    }
    if (!in_policy) {
        return false;
    }
    return GPIO_IS_VALID_GPIO((gpio_num_t)pin);
}

static boolean WriteChangePatch(byte channel, byte patch,
                                MEMFILE *midioutput)
{
    byte working = midi_changepatch | channel;
    if (WriteTime(queuedtime, midioutput))
    {
        return true;
    }
    if (mem_fwrite(&working, 1, 1, midioutput) != 1)
    {
        return true;
    }
    working = patch & 0x7F;
    if (mem_fwrite(&working, 1, 1, midioutput) != 1)
    {
        return true;
    }
    tracksize += 2;
    return false;
}

