    p->validJD = 1;
  }
}

static int
lwip_setsockopt_impl_ipv6_checksum(int s, struct lwip_sock* sock, const void* optval, socklen_t optlen)
{
  if (sock->conn->pcb.raw->protocol != IPPROTO_ICMPV6) {
    done_socket(sock);
    return EINVAL;
  }
  LWIP_SOCKOPT_CHECK_OPTLEN_CONN_PCB_TYPE(sock, optlen, int, NETCONN_RAW);
  if (*(const int*)optval < 0) {
    sock->conn->pcb.raw->chksum_reqd = 0;
  }
  else if (*(const int*)optval & 1) {
    done_socket(sock);
    return EINVAL;
  }
  else {
    sock->conn->pcb.raw->chksum_reqd = 1;
    sock->conn->pcb.raw->chksum_offset = (u16_t) * (const int*)optval;
  }
  LWIP_DEBUGF(SOCKETS_DEBUG, ("lwip_setsockopt(%d, IPPROTO_RAW, IPV6_CHECKSUM, ..) -> %d\n",
    s, sock->conn->pcb.raw->chksum_reqd));
  return 0;
}

static int get_first_free(JSValueArray *arr)
{
    JSProperty *pr1;
    int first_free;
    pr1 = (JSProperty *)&arr->arr[arr->size - 3];
    if (pr1->key != JS_UNINITIALIZED)
        first_free = pr1->hash_next >> 1;
    else
        first_free = arr->size;
    return first_free;
}

