function validateCommitMessage(command) {
  const messageMatch = command.match(/(?:-m|--message)[=\s]+["']?([^"']+)["']?/);
  if (!messageMatch) return null;
  const message = messageMatch[1];
  const issues = [];
  const conventionalCommit = /^(feat|fix|docs|style|refactor|test|chore|build|ci|perf|revert)(\(.+\))?:\s*.+/;
  if (!conventionalCommit.test(message)) {
    issues.push({
      type: 'format',
      message: 'Commit message does not follow conventional commit format',
      suggestion: 'Use format: type(scope): description (e.g., "feat(auth): add login flow")'
    });
  }
  if (message.length > 72) {
    issues.push({
      type: 'length',
      message: `Commit message too long (${message.length} chars, max 72)`,
      suggestion: 'Keep the first line under 72 characters'
    });
  }
  if (conventionalCommit.test(message)) {
    const afterColon = message.split(':')[1];
    if (afterColon && /^[A-Z]/.test(afterColon.trim())) {
      issues.push({
        type: 'capitalization',
        message: 'Subject should start with lowercase after type',
        suggestion: 'Use lowercase for the first letter of the subject'
      });
    }
  }
  if (message.endsWith('.')) {
    issues.push({
      type: 'punctuation',
      message: 'Commit message should not end with a period',
      suggestion: 'Remove the trailing period'
    });
  }
  return { message, issues };
}

function evaluate(prompt) {
  const rules = loadRules();
  const { config, skills } = rules;
  const promptLower = prompt.toLowerCase();
  const filePaths = extractFilePaths(prompt);
  const matches = [];
  for (const [name, skill] of Object.entries(skills)) {
    const match = evaluateSkill(
      name,
      skill,
      prompt,
      promptLower,
      filePaths,
      rules
    );
    if (match && match.score >= config.minConfidenceScore) {
      matches.push(match);
    }
  }
  if (matches.length === 0) {
    return '';
  }
  matches.sort((a, b) => {
    if (b.score !== a.score) return b.score - a.score;
    return b.priority - a.priority;
  });
  const topMatches = matches.slice(0, config.maxSkillsToShow);
  const relatedSkills = getRelatedSkills(topMatches, skills);
  let output = '<user-prompt-submit-hook>\n';
  output += 'SKILL ACTIVATION REQUIRED\n\n';
  if (filePaths.length > 0) {
    output += `Detected file paths: ${filePaths.join(', ')}\n\n`;
  }
  output += 'Matched skills (ranked by relevance):\n';
  for (let i = 0; i < topMatches.length; i++) {
    const match = topMatches[i];
    const confidence = formatConfidence(match.score, config.minConfidenceScore);
    output += `${i + 1}. ${match.name} (${confidence} confidence)\n`;
    if (config.showMatchReasons && match.reasons.length > 0) {
      output += `   Matched: ${match.reasons.slice(0, 3).join(', ')}\n`;
    }
  }
  if (relatedSkills.length > 0) {
    output += `\nRelated skills to consider: ${relatedSkills.join(', ')}\n`;
  }
  output += '\nBefore implementing, you MUST:\n';
  output += '1. EVALUATE: State YES/NO for each skill with brief reasoning\n';
  output += '2. ACTIVATE: Invoke the Skill tool for each YES skill\n';
  output += '3. IMPLEMENT: Only proceed after skill activation\n';
  output += '\nExample evaluation:\n';
  output += `- ${topMatches[0].name}: YES - [your reasoning]\n`;
  if (topMatches.length > 1) {
    output += `- ${topMatches[1].name}: NO - [your reasoning]\n`;
  }
  output += '\nDO NOT skip this step. Invoke relevant skills NOW.\n';
  output += '</user-prompt-submit-hook>';
  return output;
}

function claudeToOpenAIRequest(model, body, stream) {
  const result = {
    model: model,
    messages: [],
    stream: stream
  };
  if (body.max_tokens) {
    result.max_tokens = adjustMaxTokens(body);
  }
  if (body.temperature !== undefined) {
    result.temperature = body.temperature;
  }
  if (body.system) {
    const systemContent = Array.isArray(body.system)
      ? body.system.map(s => s.text || "").join("\n")
      : body.system;
    if (systemContent) {
      result.messages.push({
        role: "system",
        content: systemContent
      });
    }
  }
  if (body.messages && Array.isArray(body.messages)) {
    for (let i = 0; i < body.messages.length; i++) {
      const msg = body.messages[i];
      const converted = convertClaudeMessage(msg);
      if (converted) {
        if (Array.isArray(converted)) {
          result.messages.push(...converted);
        } else {
          result.messages.push(converted);
        }
      }
    }
  }
  fixMissingToolResponses(result.messages);
  if (body.tools && Array.isArray(body.tools)) {
    result.tools = body.tools.map(tool => ({
      type: "function",
      function: {
        name: tool.name,
        description: String(tool.description || ""),
        parameters: tool.input_schema || { type: "object", properties: {} }
      }
    }));
  }
  if (body.tool_choice) {
    result.tool_choice = convertToolChoice(body.tool_choice);
  }
  return result;
}

