static int add_r0kh(struct hostapd_bss_config *bss, char *value)
{
	struct ft_remote_r0kh *r0kh;
	char *pos, *next;
	r0kh = os_zalloc(sizeof(*r0kh));
	if (r0kh == NULL)
		return -1;
	pos = value;
	next = os_strchr(pos, ' ');
	if (next)
		*next++ = '\0';
	if (next == NULL || hwaddr_aton(pos, r0kh->addr)) {
		wpa_printf(MSG_ERROR, "Invalid R0KH MAC address: '%s'", pos);
		os_free(r0kh);
		return -1;
	}
	pos = next;
	next = os_strchr(pos, ' ');
	if (next)
		*next++ = '\0';
	if (next == NULL || next - pos > FT_R0KH_ID_MAX_LEN) {
		wpa_printf(MSG_ERROR, "Invalid R0KH-ID: '%s'", pos);
		os_free(r0kh);
		return -1;
	}
	r0kh->id_len = next - pos - 1;
	os_memcpy(r0kh->id, pos, r0kh->id_len);
	pos = next;
	if (rkh_derive_key(pos, r0kh->key, sizeof(r0kh->key)) < 0) {
		wpa_printf(MSG_ERROR, "Invalid R0KH key: '%s'", pos);
		os_free(r0kh);
		return -1;
	}
	r0kh->next = bss->r0kh_list;
	bss->r0kh_list = r0kh;
	return 0;
}

def __call__(
        self,
        images: Union[
            Image.Image, np.ndarray, "torch.Tensor", List[Image.Image], List[np.ndarray], List["torch.Tensor"]  # noqa
        ],
        return_tensors: Optional[Union[str, TensorType]] = None,
        **kwargs
    ) -> BatchFeature:



        # Input type checking for clearer error
        valid_images = False

        # Check that images has a valid type
        if isinstance(images, (Image.Image, np.ndarray)) or is_torch_tensor(images):
            valid_images = True
        elif isinstance(images, (list, tuple)):
            if len(images) == 0 or isinstance(images[0], (Image.Image, np.ndarray)) or is_torch_tensor(images[0]):
                valid_images = True

        if not valid_images:
            raise ValueError(
                "Images must of type `PIL.Image.Image`, `np.ndarray` or `torch.Tensor` (single example), "
                "`List[PIL.Image.Image]`, `List[np.ndarray]` or `List[torch.Tensor]` (batch of examples)."
            )

        is_batched = bool(
            isinstance(images, (list, tuple))
            and (isinstance(images[0], (Image.Image, np.ndarray)) or is_torch_tensor(images[0]))
        )

        if not is_batched:
            images = [images]

        # transformations (resizing + normalization)
        if self.do_resize and self.size is not None:
            images = [self.resize(image, size=self.size, resample=self.resample) for image in images]

        if self.do_normalize:
            images = [self.normalize(image) for image in images]

        # color quantize from (batch_size, height, width, 3) to (batch_size, height, width)
        images = np.array(images)
        images = color_quantize(images, self.clusters).reshape(images.shape[:-1])

        # flatten to (batch_size, height*width)
        batch_size = images.shape[0]
        images = images.reshape(batch_size, -1)

        # return as BatchFeature
        data = {"pixel_values": images}
        encoded_inputs = BatchFeature(data=data, tensor_type=return_tensors)

        return encoded_inputs

double js_sqrt(double x)
{
	double z;
	int 	sign = (int)0x80000000; 
	unsigned r,t1,s1,ix1,q1;
	int ix0,s0,q,m,t,i;
	EXTRACT_WORDS(ix0, ix1, x);
	if((ix0&0x7ff00000)==0x7ff00000) {			
	    return x*x+x;		
	} 
	if(ix0<=0) {
	    if(((ix0&(~sign))|ix1)==0) return x;
	    else if(ix0<0)
		return (x-x)/(x-x);		
	}
	m = (ix0>>20);
	if(m==0) {				
	    while(ix0==0) {
		m -= 21;
		ix0 |= (ix1>>11); ix1 <<= 21;
	    }
	    for(i=0;(ix0&0x00100000)==0;i++) ix0<<=1;
	    m -= i-1;
	    ix0 |= (ix1>>(32-i));
	    ix1 <<= i;
	}
	m -= 1023;	
	ix0 = (ix0&0x000fffff)|0x00100000;
	if(m&1){	
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	}
	m >>= 1;	
	ix0 += ix0 + ((ix1&sign)>>31);
	ix1 += ix1;
	q = q1 = s0 = s1 = 0;	
	r = 0x00200000;		
	while(r!=0) {
	    t = s0+r; 
	    if(t<=ix0) { 
		s0   = t+r; 
		ix0 -= t; 
		q   += r; 
	    } 
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	    r>>=1;
	}
	r = sign;
	while(r!=0) {
	    t1 = s1+r; 
	    t  = s0;
	    if((t<ix0)||((t==ix0)&&(t1<=ix1))) { 
		s1  = t1+r;
		if(((t1&sign)==sign)&&(s1&sign)==0) s0 += 1;
		ix0 -= t;
		if (ix1 < t1) ix0 -= 1;
		ix1 -= t1;
		q1  += r;
	    }
	    ix0 += ix0 + ((ix1&sign)>>31);
	    ix1 += ix1;
	    r>>=1;
	}
	if((ix0|ix1)!=0) {
	    z = one-tiny; 
	    if (z>=one) {
	        z = one+tiny;
	        if (q1==(unsigned)0xffffffff) { q1=0; q += 1;}
		else if (z>one) {
		    if (q1==(unsigned)0xfffffffe) q+=1;
		    q1+=2; 
		} else
	            q1 += (q1&1);
	    }
	}
	ix0 = (q>>1)+0x3fe00000;
	ix1 =  q1>>1;
	if ((q&1)==1) ix1 |= sign;
	ix0 += (m <<20);
	return float64_from_u32(ix0, ix1);
}

void s5BAudioClockTimers()
{
	if((s5b_apu.ctr&0xF) == 0)
	{
		uint8_t i;
		for(i = 0; i < 3; i++)
		{
			if(s5b_apu.freqCtr[i])
				s5b_apu.freqCtr[i]--;
			if(s5b_apu.freqCtr[i] == 0)
			{
				s5b_apu.freqCtr[i] = s5b_apu.freq[i];
				s5b_apu.cycle[i]++;
			}
		}
		if(s5b_apu.noiseFreqCtr)
			s5b_apu.noiseFreqCtr--;
		if(s5b_apu.noiseFreqCtr == 0)
		{
			s5b_apu.noiseFreqCtr = s5b_apu.noiseFreq;
			if(s5b_apu.noiseReg&1) s5b_apu.noiseReg ^= 0x24000;
			s5b_apu.noiseReg >>= 1;
		}
		if(s5b_apu.envFreqCtr)
			s5b_apu.envFreqCtr--;
		if(s5b_apu.envFreqCtr == 0)
		{
			s5b_apu.envFreqCtr = s5b_apu.envFreq;
			if(s5b_apu.envStep >= 63)
			{
				if(s5b_apu.envRepeat)
					s5b_apu.envStep = 0;
			}
			else
				s5b_apu.envStep++;
			s5b_apu.envVol = s5b_apu.volTbl[s5b_apu.envShapeTbl[s5b_apu.envShape][s5b_apu.envStep]];
		}
	}
	s5b_apu.ctr++;
}

scanvideo_scanline_buffer_t *__video_time_critical_func(scanvideo_begin_scanline_generation_linked)(uint n,
        bool block) {
    full_scanline_buffer_t *fsb;
    DEBUG_PINS_SET(video_link, 1);
    DEBUG_PINS_SET(video_generation, 1);
    do {
        uint32_t save = spin_lock_blocking(shared_state.free_list.lock);
        fsb = shared_state.free_list.free_list;
        if (fsb) {
            full_scanline_buffer_t *fsb_tail = fsb;
            for(uint i=1; i<n || fsb_tail; i++) {
                fsb_tail = fsb_tail->next;
            }
            if (fsb_tail) {
                shared_state.free_list.free_list = fsb_tail->next;
                fsb_tail->next = NULL;
            } else {
                fsb = NULL;
            }
        }
        spin_unlock(shared_state.free_list.lock, save);
        if (fsb) {
            full_scanline_buffer_t *fsb_tail = fsb;
            while (fsb_tail) {
                full_scanline_buffer_t *fsb_next = fsb_tail->next;
                fsb_tail->core.link = fsb_next ? &fsb_next->core : NULL;
                fsb_tail->next = NULL;
                fsb_tail = fsb_next;
            }
            save = spin_lock_blocking(shared_state.scanline.lock);
            DEBUG_PINS_SET(video_timing, 1);
#if PICO_SCANVIDEO_ENABLE_SCANLINE_ASSERTIONS
            list_prepend(&shared_state.scanline.generating_list, fsb);
#endif
            uint32_t scanline_id = shared_state.scanline.next_scanline_id;
            if (!is_scanline_after(scanline_id, shared_state.scanline.last_scanline_id)) {
                scanline_id = scanline_id_after(shared_state.scanline.last_scanline_id);
            }
            shared_state.scanline.last_scanline_id = scanline_id;
            scanvideo_scanline_buffer_t *fsb_core = &fsb->core;
            while (fsb_core) {
                fsb_core->scanline_id = scanline_id;
                fsb_core = fsb_core->link;
            }
            DEBUG_PINS_CLR(video_timing, 1);
            spin_unlock(shared_state.scanline.lock, save);
            break;
        }
        if (block) {
            __wfe();
        }
    } while (block);
    DEBUG_PINS_CLR(video_link, 1);
    DEBUG_PINS_CLR(video_generation, 1);
    fsb->core.link_after = 0;
    return (scanvideo_scanline_buffer_t *) fsb;
}

