ASTNode *parse_if(ParserContext *ctx, Lexer *l)
{
    Token if_token = lexer_next(l); 
    ASTNode *cond = parse_expression(ctx, l);
    check_assignment_condition(cond);
    ASTNode *then_b = NULL;
    if (lexer_peek(l).type == TOK_LBRACE)
    {
        then_b = parse_block(ctx, l);
    }
    else
    {
        if (g_config.misra_mode)
        {
            zerror_at(lexer_peek(l), "MISRA Rule 15.6");
        }
        enter_scope(ctx);
        ASTNode *s = parse_statement(ctx, l);
        exit_scope(ctx);
        then_b = ast_create(NODE_BLOCK);
        then_b->block.statements = s;
    }
    ASTNode *else_b = NULL;
    skip_comments(l);
    if (lexer_peek(l).type == TOK_IDENT && strncmp(lexer_peek(l).start, "else", 4) == 0)
    {
        lexer_next(l);
        if (lexer_peek(l).type == TOK_IDENT && strncmp(lexer_peek(l).start, "if", 2) == 0)
        {
            else_b = parse_if(ctx, l);
        }
        else if (lexer_peek(l).type == TOK_LBRACE)
        {
            else_b = parse_block(ctx, l);
        }
        else
        {
            if (g_config.misra_mode)
            {
                zerror_at(lexer_peek(l), "MISRA Rule 15.6");
            }
            enter_scope(ctx);
            ASTNode *s = parse_statement(ctx, l);
            exit_scope(ctx);
            else_b = ast_create(NODE_BLOCK);
            else_b->block.statements = s;
        }
    }
    ASTNode *n = ast_create(NODE_IF);
    n->token = if_token;
    n->if_stmt.condition = cond;
    n->if_stmt.then_body = then_b;
    n->if_stmt.else_body = else_b;
    return n;
}

function sweepCacheDir(cacheDir, now) {
    try {
        if (!fs.existsSync(cacheDir))
            return;
        const entries = fs.readdirSync(cacheDir, { withFileTypes: true });
        const survivors = [];
        for (const entry of entries) {
            if (!entry.isFile() || !entry.name.endsWith(".json"))
                continue;
            const fullPath = path.join(cacheDir, entry.name);
            try {
                const stat = fs.statSync(fullPath);
                if (now - stat.mtimeMs <= MAX_CACHE_AGE_MS) {
                    fs.unlinkSync(fullPath);
                    continue;
                }
                survivors.push({ fullPath, mtimeMs: stat.mtimeMs });
            }
            catch {
            }
        }
        if (survivors.length > MAX_CACHE_ENTRIES) {
            survivors.sort((a, b) => a.mtimeMs - b.mtimeMs);
            const toDelete = survivors.length - MAX_CACHE_ENTRIES;
            for (let i = 0; i < toDelete; i += 1) {
                try {
                    fs.unlinkSync(survivors[i].fullPath);
                }
                catch {
                }
            }
        }
    }
    catch {
    }
}

static char *GetFullPath(char *base_filename, char *path)
{
    char *basedir, *result;
    char *p;
    if (path[0] == DIR_SEPARATOR)
    {
        return strdup(path);
    }
#ifdef _WIN32
    if (isalpha(path[0]) && path[1] == ':' && path[2] == DIR_SEPARATOR)
    {
        return strdup(path);
    }
#endif
    path = M_StringReplace(path, "/", DIR_SEPARATOR_S);
    basedir = strdup(base_filename);
    p = strrchr(basedir, DIR_SEPARATOR);
    if (p != NULL)
    {
        p[1] = '\0';
        result = M_StringJoin(basedir, path, NULL);
    }
    else
    {
        result = strdup(path);
    }
    free(basedir);
    free(path);
    return result;
}

