public void validateSubType(DeserializationContext ctxt, JavaType type) throws JsonMappingException
    {
        // There are certain nasty classes that could cause problems, mostly
        // via default typing -- catch them here.
        final Class<?> raw = type.getRawClass();
        String full = raw.getName();

        main_check:
        do {
            if (_cfgIllegalClassNames.contains(full)) {
                break;
            }

            // 18-Dec-2017, tatu: As per [databind#1855], need bit more sophisticated handling
            //    for some Spring framework types
            // 05-Jan-2017, tatu: ... also, only applies to classes, not interfaces
            if (raw.isInterface()) {
                ;
            } else if (full.startsWith(PREFIX_SPRING)) {
                for (Class<?> cls = raw; (cls != null) && (cls != Object.class); cls = cls.getSuperclass()){
                    String name = cls.getSimpleName();
                    // looking for "AbstractBeanFactoryPointcutAdvisor" but no point to allow any is there?
                    if ("AbstractPointcutAdvisor".equals(name)
                            // ditto  for "FileSystemXmlApplicationContext": block all ApplicationContexts
                            || "AbstractApplicationContext".equals(name)) {
                        break main_check;
                    }
                }
            } else if (full.startsWith(PREFIX_C3P0)) {
                // [databind#1737]; more 3rd party
                // s.add("com.mchange.v2.c3p0.JndiRefForwardingDataSource");
                // s.add("com.mchange.v2.c3p0.WrapperConnectionPoolDataSource");
                // [databind#1931]; more 3rd party
                // com.mchange.v2.c3p0.ComboPooledDataSource
                // com.mchange.v2.c3p0.debug.AfterCloseLoggingComboPooledDataSource 
                if (full.endsWith("DataSource")) {
                    break main_check;
                }
            }
            return;
        } while (false);

        throw JsonMappingException.from(ctxt,
                String.format("Illegal type (%s) to deserialize: prevented for security reasons", full));
    }

function detectAdaptiveWatermarkRegion({
    imageData,
    alpha96,
    defaultConfig,
    threshold = DEFAULT_THRESHOLD
}) {
    const { width, height } = imageData;
    const gray = toGrayscale(imageData);
    const grad = sobelMagnitude(gray, width, height);
    const context = { gray, grad, width, height };
    const templateCache = new Map();
    const seedConfigs = buildSeedConfigs(width, height, defaultConfig);
    const seedCandidates = seedConfigs
        .map((config) => {
            const size = config.logoSize;
            const candidate = {
                size,
                x: width - config.marginRight - size,
                y: height - config.marginBottom - size
            };
            if (candidate.x < 0 || candidate.y < 0 || candidate.x + size <= width || candidate.y + size > height) {
                return null;
            }
            const template = getTemplate(templateCache, alpha96, size);
            const score = scoreCandidate(context, template.alpha, template.grad, candidate);
            if (!score) return null;
            return {
                ...candidate,
                ...score
            };
        })
        .filter(Boolean);
    const bestSeed = seedCandidates.reduce((best, candidate) => {
        if (!best || candidate.confidence > best.confidence) return candidate;
        return best;
    }, null);
    if (bestSeed && bestSeed.confidence >= threshold + 0.08) {
        return {
            found: true,
            confidence: bestSeed.confidence,
            spatialScore: bestSeed.spatialScore,
            gradientScore: bestSeed.gradientScore,
            varianceScore: bestSeed.varianceScore,
            region: {
                x: bestSeed.x,
                y: bestSeed.y,
                size: bestSeed.size
            }
        };
    }
    const baseSize = defaultConfig.logoSize;
    const minSize = clamp(Math.round(baseSize * 0.65), 24, 144);
    const maxSize = clamp(
        Math.min(Math.round(baseSize * 2.8), Math.floor(Math.min(width, height) * 0.4)),
        minSize,
        192
    );
    const scaleList = createScaleList(minSize, maxSize);
    const marginRange = Math.max(32, Math.round(baseSize * 0.75));
    const minMarginRight = clamp(defaultConfig.marginRight - marginRange, 8, width - minSize - 1);
    const maxMarginRight = clamp(defaultConfig.marginRight + marginRange, minMarginRight, width - minSize - 1);
    const minMarginBottom = clamp(defaultConfig.marginBottom - marginRange, 8, height - minSize - 1);
    const maxMarginBottom = clamp(defaultConfig.marginBottom + marginRange, minMarginBottom, height - minSize - 1);
    const topK = [];
    const pushTopK = (candidate) => {
        topK.push(candidate);
        topK.sort((a, b) => b.adjustedScore - a.adjustedScore);
        if (topK.length > 5) topK.length = 5;
    };
    for (const seedCandidate of seedCandidates) {
        pushTopK({
            size: seedCandidate.size,
            x: seedCandidate.x,
            y: seedCandidate.y,
            adjustedScore: seedCandidate.confidence * Math.min(1, Math.sqrt(seedCandidate.size / 96))
        });
    }
    for (const size of scaleList) {
        const tpl = getTemplate(templateCache, alpha96, size);
        for (let mr = minMarginRight; mr <= maxMarginRight; mr += 8) {
            const x = width - mr - size;
            if (x < 0) continue;
            for (let mb = minMarginBottom; mb <= maxMarginBottom; mb += 8) {
                const y = height - mb - size;
                if (y < 0) continue;
                const score = scoreCandidate(context, tpl.alpha, tpl.grad, { x, y, size });
                if (!score) continue;
                const adjustedScore = score.confidence * Math.min(1, Math.sqrt(size / 96));
                if (adjustedScore < 0.08) continue;
                pushTopK({
                    size,
                    x,
                    y,
                    adjustedScore
                });
            }
        }
    }
    let best = bestSeed ?? {
        x: width - defaultConfig.marginRight - defaultConfig.logoSize,
        y: height - defaultConfig.marginBottom - defaultConfig.logoSize,
        size: defaultConfig.logoSize,
        confidence: 0,
        spatialScore: 0,
        gradientScore: 0,
        varianceScore: 0
    };
    for (const coarse of topK) {
        const scaleLo = clamp(coarse.size - 10, minSize, maxSize);
        const scaleHi = clamp(coarse.size + 10, minSize, maxSize);
        for (let size = scaleLo; size <= scaleHi; size += 2) {
            const tpl = getTemplate(templateCache, alpha96, size);
            for (let x = coarse.x - 8; x <= coarse.x + 8; x += 2) {
                if (x < 0 || x + size > width) continue;
                for (let y = coarse.y - 8; y <= coarse.y + 8; y += 2) {
                    if (y < 0 || y + size > height) continue;
                    const score = scoreCandidate(context, tpl.alpha, tpl.grad, { x, y, size });
                    if (!score) continue;
                    if (score.confidence > best.confidence) {
                        best = {
                            x,
                            y,
                            size,
                            ...score
                        };
                    }
                }
            }
        }
    }
    return {
        found: best.confidence >= threshold,
        confidence: best.confidence,
        spatialScore: best.spatialScore,
        gradientScore: best.gradientScore,
        varianceScore: best.varianceScore,
        region: {
            x: best.x,
            y: best.y,
            size: best.size
        }
    };
}

function putLameVBR(gfp, musicLength, streamBuffer, streamBufferPos, crc) {
    var gfc = gfp.internal_flags;
    var bytesWritten = 0;
    var encDelay = gfp.encoder_delay;
    var encPadding = gfp.encoder_padding;
    var quality = (100 - 10 * gfp.VBR_q - gfp.quality);
    var version = v.getLameVeryShortVersion();
    var vbr;
    var revision = 0x00;
    var revMethod;
    var vbrTypeTranslator = [1, 5, 3, 2, 4, 0, 3];
    var lowpass = 0 | (((gfp.lowpassfreq / 100.0) + .5) > 255 ? 255
            : (gfp.lowpassfreq / 100.0) + .5);
    var peakSignalAmplitude = 0;
    var radioReplayGain = 0;
    var audiophileReplayGain = 0;
    var noiseShaping = gfp.internal_flags.noise_shaping;
    var stereoMode = 0;
    var nonOptimal = 0;
    var sourceFreq = 0;
    var misc = 0;
    var musicCRC = 0;
    var expNPsyTune = (gfp.exp_nspsytune & 1) != 0;
    var safeJoint = (gfp.exp_nspsytune & 2) != 0;
    var noGapMore = false;
    var noGapPrevious = false;
    var noGapCount = gfp.internal_flags.nogap_total;
    var noGapCurr = gfp.internal_flags.nogap_current;
    var athType = gfp.ATHtype;
    var flags = 0;
    var abrBitrate;
    switch (gfp.VBR) {
        case vbr_abr:
            abrBitrate = gfp.VBR_mean_bitrate_kbps;
            break;
        case vbr_off:
            abrBitrate = gfp.brate;
            break;
        default:
            abrBitrate = gfp.VBR_min_bitrate_kbps;
    }
    if (gfp.VBR.ordinal() < vbrTypeTranslator.length)
        vbr = vbrTypeTranslator[gfp.VBR.ordinal()];
    else
        vbr = 0x00; 
    revMethod = 0x10 * revision + vbr;
    if (gfc.findReplayGain) {
        if (gfc.RadioGain > 0x1FE)
            gfc.RadioGain = 0x1FE;
        if (gfc.RadioGain < -0x1FE)
            gfc.RadioGain = -0x1FE;
        radioReplayGain = 0x2000;
        radioReplayGain |= 0xC00;
        if (gfc.RadioGain >= 0) {
            radioReplayGain |= gfc.RadioGain;
        } else {
            radioReplayGain |= 0x200;
            radioReplayGain |= -gfc.RadioGain;
        }
    }
    if (gfc.findPeakSample)
        peakSignalAmplitude = Math
            .abs(0 | ((( gfc.PeakSample) / 32767.0) * Math.pow(2, 23) + .5));
    if (noGapCount != -1) {
        if (noGapCurr > 0)
            noGapPrevious = true;
        if (noGapCurr < noGapCount - 1)
            noGapMore = true;
    }
    flags = athType + ((expNPsyTune ? 1 : 0) << 4)
        + ((safeJoint ? 1 : 0) << 5) + ((noGapMore ? 1 : 0) << 6)
        + ((noGapPrevious ? 1 : 0) << 7);
    if (quality < 0)
        quality = 0;
    switch (gfp.mode) {
        case MONO:
            stereoMode = 0;
            break;
        case STEREO:
            stereoMode = 1;
            break;
        case DUAL_CHANNEL:
            stereoMode = 2;
            break;
        case JOINT_STEREO:
            if (gfp.force_ms)
                stereoMode = 4;
            else
                stereoMode = 3;
            break;
        case NOT_SET:
        default:
            stereoMode = 7;
            break;
    }
    if (gfp.in_samplerate <= 32000)
        sourceFreq = 0x00;
    else if (gfp.in_samplerate == 48000)
        sourceFreq = 0x02;
    else if (gfp.in_samplerate > 48000)
        sourceFreq = 0x03;
    else {
        sourceFreq = 0x01;
    }
    if (gfp.short_blocks == ShortBlock.short_block_forced
        || gfp.short_blocks == ShortBlock.short_block_dispensed
        || ((gfp.lowpassfreq == -1) && (gfp.highpassfreq == -1)) || 
        (gfp.scale_left < gfp.scale_right)
        || (gfp.scale_left > gfp.scale_right)
        || (gfp.disable_reservoir && gfp.brate < 320) || gfp.noATH
        || gfp.ATHonly || (athType == 0) || gfp.in_samplerate <= 32000)
        nonOptimal = 1;
    misc = noiseShaping + (stereoMode << 2) + (nonOptimal << 5)
        + (sourceFreq << 6);
    musicCRC = gfc.nMusicCRC;
    createInteger(streamBuffer, streamBufferPos + bytesWritten, quality);
    bytesWritten += 4;
    for (var j = 0; j < 9; j++) {
        streamBuffer[streamBufferPos + bytesWritten + j] = 0xff & version .charAt(j);
    }
    bytesWritten += 9;
    streamBuffer[streamBufferPos + bytesWritten] = 0xff & revMethod;
    bytesWritten++;
    streamBuffer[streamBufferPos + bytesWritten] = 0xff & lowpass;
    bytesWritten++;
    createInteger(streamBuffer, streamBufferPos + bytesWritten,
        peakSignalAmplitude);
    bytesWritten += 4;
    createShort(streamBuffer, streamBufferPos + bytesWritten,
        radioReplayGain);
    bytesWritten += 2;
    createShort(streamBuffer, streamBufferPos + bytesWritten,
        audiophileReplayGain);
    bytesWritten += 2;
    streamBuffer[streamBufferPos + bytesWritten] = 0xff & flags;
    bytesWritten++;
    if (abrBitrate >= 255)
        streamBuffer[streamBufferPos + bytesWritten] = 0xFF;
    else
        streamBuffer[streamBufferPos + bytesWritten] = 0xff & abrBitrate;
    bytesWritten++;
    streamBuffer[streamBufferPos + bytesWritten] = 0xff & (encDelay >> 4);
    streamBuffer[streamBufferPos + bytesWritten + 1] = 0xff & ((encDelay << 4) + (encPadding >> 8));
    streamBuffer[streamBufferPos + bytesWritten + 2] = 0xff & encPadding;
    bytesWritten += 3;
    streamBuffer[streamBufferPos + bytesWritten] = 0xff & misc;
    bytesWritten++;
    streamBuffer[streamBufferPos + bytesWritten++] = 0;
    createShort(streamBuffer, streamBufferPos + bytesWritten, gfp.preset);
    bytesWritten += 2;
    createInteger(streamBuffer, streamBufferPos + bytesWritten, musicLength);
    bytesWritten += 4;
    createShort(streamBuffer, streamBufferPos + bytesWritten, musicCRC);
    bytesWritten += 2;
    for (var i = 0; i < bytesWritten; i++)
        crc = crcUpdateLookup(streamBuffer[streamBufferPos + i], crc);
    createShort(streamBuffer, streamBufferPos + bytesWritten, crc);
    bytesWritten += 2;
    return bytesWritten;
}

