    const bounds = getPetWindowBounds();
    if (!bounds) return null;
    return applyPetWindowBounds({ ...bounds, x, y });
  }
  function isPetHidden() {
    return petHidden;
  }
  function showPetWindows() {
    const win = getRenderWindow();
    if (isLiveWindow(win)) {
      win.showInactive();
