function createModel() {
  const scene = new THREE.Group();
  const batMat = new THREE.MeshPhysicalMaterial({
    color: 0x6a0dad,
    emissive: 0x6a0dad,
    emissiveIntensity: 0.15,
    roughness: 0.4,
    metalness: 0.1,
    side: THREE.DoubleSide
  });
  const membraneMat = new THREE.MeshPhysicalMaterial({
    color: 0x5a0aad,
    emissive: 0x5a0aad,
    emissiveIntensity: 0.1,
    transparent: true,
    opacity: 0.6,
    roughness: 0.5,
    metalness: 0.0,
    side: THREE.DoubleSide
  });
  function makeBat() {
    const group = new THREE.Group();
    const bodyGeo = new THREE.SphereGeometry(0.18, 16, 16);
    const body = new THREE.Mesh(bodyGeo, batMat);
    body.scale.set(1.0, 2.2, 0.8);
    group.add(body);
    const headGeo = new THREE.SphereGeometry(0.18, 16, 16);
    const head = new THREE.Mesh(headGeo, batMat);
    head.position.set(0, 0.45, 0.05);
    group.add(head);
    const snoutGeo = new THREE.SphereGeometry(0.07, 12, 12);
    const snout = new THREE.Mesh(snoutGeo, batMat);
    snout.scale.set(0.8, 0.6, 1.0);
    snout.position.set(0, 0.4, 0.2);
    group.add(snout);
    const earGeo = new THREE.ConeGeometry(0.06, 0.2, 8);
    [-1, 1].forEach(s => {
      const ear = new THREE.Mesh(earGeo, batMat);
      ear.position.set(0.1 * s, 0.62, 0.02);
      ear.rotation.z = -0.15 * s;
      group.add(ear);
    });
    const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff4444 });
    const eyeGeo = new THREE.SphereGeometry(0.035, 8, 8);
    [-1, 1].forEach(s => {
      const eye = new THREE.Mesh(eyeGeo, eyeMat);
      eye.position.set(0.08 * s, 0.48, 0.18);
      group.add(eye);
    });
    function makeWing(xSign) {
      const wingGroup = new THREE.Group();
      const memShape = new THREE.Shape();
      memShape.moveTo(0, 0);
      memShape.quadraticCurveTo(0.4 * xSign, 0.3, 0.8 * xSign, 0.15);
      memShape.quadraticCurveTo(0.7 * xSign, 0.0, 0.9 * xSign, -0.1);
      memShape.quadraticCurveTo(0.75 * xSign, -0.15, 0.6 * xSign, -0.2);
      memShape.quadraticCurveTo(0.45 * xSign, -0.1, 0.35 * xSign, -0.25);
      memShape.quadraticCurveTo(0.15 * xSign, -0.15, 0, -0.3);
      memShape.closePath();
      const memGeo = new THREE.ShapeGeometry(memShape);
      const membrane = new THREE.Mesh(memGeo, membraneMat);
      membrane.position.z = 0.005;
      wingGroup.add(membrane);
      const memBack = new THREE.Mesh(memGeo, membraneMat);
      memBack.position.z = -0.005;
      wingGroup.add(memBack);
      return wingGroup;
    }
    const leftWing = makeWing(-1);
    leftWing.position.set(-0.12, 0.05, 0);
    const rightWing = makeWing(1);
    rightWing.position.set(0.12, 0.05, 0);
    group.add(leftWing);
    group.add(rightWing);
    [-1, 1].forEach(s => {
      const legGeo = new THREE.CylinderGeometry(0.015, 0.01, 0.12, 6);
      const leg = new THREE.Mesh(legGeo, batMat);
      leg.position.set(0.06 * s, -0.42, 0);
      group.add(leg);
      const clawGeo = new THREE.CylinderGeometry(0.006, 0.002, 0.06, 4);
      [-1, 0, 1].forEach(t => {
        const claw = new THREE.Mesh(clawGeo, batMat);
        claw.position.set(0.06 * s + 0.015 * t, -0.49, 0);
        claw.rotation.z = 0.15 * t;
        group.add(claw);
      });
    });
    group.userData.leftWing = leftWing;
    group.userData.rightWing = rightWing;
    return group;
  }
  const bats = [];
  for (var i = 0; i < 3; i++) {
    var pivot = new THREE.Group();
    var bat = makeBat();
    bat.scale.set(0.7, 0.7, 0.7);
    bat.position.x = 1.5;
    bat.rotation.y = Math.PI;
    bat.rotation.x = -0.7;
    pivot.rotation.y = (Math.PI * 2 / 3) * i;
    bat.position.y = (i - 1) * 0.3;
    pivot.add(bat);
    scene.add(pivot);
    bats.push({ pivot: pivot, bat: bat });
  }
  scene.userData.bats = bats;
  return scene;
}

static void emit_trait_defs_internal(ParserContext *ctx, ASTNode *node, VisitedModules **visited,
                                     int depth)
{
    if (depth > 1024)
    {
        zfatal("Infinite recursion detected in emit_trait_defs (ctx, circular imports?)");
    }
    while (node)
    {
        if (node->type == NODE_IMPORT)
        {
            if (!is_module_visited(*visited, node->import_stmt.path))
            {
                mark_module_visited(visited, node->import_stmt.path);
                emit_trait_defs_internal(ctx, node->import_stmt.module_root, visited, depth + 1);
            }
            node = node->next;
            continue;
        }
        if (node->type == NODE_TRAIT)
        {
            if (node->trait.generic_param_count > 0)
            {
                node = node->next;
                continue;
            }
            if (node->cfg_condition)
            {
                EMIT(ctx, "#if %s\n", node->cfg_condition);
            }
            EMIT(ctx, "typedef struct %s_VTable {\n", node->trait.name);
            emitter_indent(&ctx->emitter);
            ASTNode *m = node->trait.methods;
            while (m)
            {
                char *ret_safe = substitute_proto_self(m->func.ret_type, "void*");
                const char *orig = parse_original_method_name(m->func.name);
                EMIT(ctx, "%s (*%s)(", ret_safe, orig);
                zfree(ret_safe);
                int has_self = (m->func.args && strstr(m->func.args, "self"));
                if (!has_self)
                {
                    EMIT(ctx, "void* self");
                }
                if (m->func.args && strlen(m->func.args) > 0)
                {
                    char *args_safe = replace_type_str(m->func.args, "Self", "void*", NULL, NULL);
                    if (strstr(args_safe, "void* self") == args_safe ||
                        strstr(args_safe, "const void* self") == args_safe)
                    {
                        EMIT(ctx, "%s", args_safe);
                    }
                    else if (strlen(args_safe) > 0)
                    {
                        if (!has_self)
                        {
                            EMIT(ctx, ", ");
                        }
                        EMIT(ctx, "%s", args_safe);
                    }
                    zfree(args_safe);
                }
                EMIT(ctx, ");\n");
                m = m->next;
            }
            emitter_dedent(&ctx->emitter);
            EMIT(ctx, "} %s_VTable;\n", node->trait.name);
            EMIT(ctx, "typedef struct %s { void *self; %s_VTable *vtable; } %s;\n",
                 node->trait.name, node->trait.name, node->trait.name);
            if (node->cfg_condition)
            {
                EMIT(ctx, "#endif\n");
            }
            EMIT(ctx, "\n");
        }
        node = node->next;
    }
}

