    }
}

int
lwip_gethostbyname_r(const char *name, struct hostent *ret, char *buf,
                     size_t buflen, struct hostent **result, int *h_errnop)
{
  err_t err;
  struct gethostbyname_r_helper *h;
  char *hostname;
  size_t namelen;
  int lh_errno;
  if (h_errnop == NULL) {
    h_errnop = &lh_errno;
  }
  if (result == NULL) {
    *h_errnop = EINVAL;
    return -1;
  }
  *result = NULL;
  if ((name == NULL) || (ret == NULL) || (buf == NULL)) {
    *h_errnop = EINVAL;
    return -1;
  }
  namelen = strlen(name);
  if (buflen < (sizeof(struct gethostbyname_r_helper) + LWIP_MEM_ALIGN_BUFFER(namelen + 1))) {
    *h_errnop = ERANGE;
    return -1;
  }
  h = (struct gethostbyname_r_helper *)LWIP_MEM_ALIGN(buf);
  hostname = ((char *)h) + sizeof(struct gethostbyname_r_helper);
  err = netconn_gethostbyname(name, &h->addr);
  if (err != ERR_OK) {
    LWIP_DEBUGF(DNS_DEBUG, ("lwip_gethostbyname(%s) failed, err=%d\n", name, err));
    *h_errnop = HOST_NOT_FOUND;
    return -1;
  }
  MEMCPY(hostname, name, namelen);
  hostname[namelen] = 0;
  h->addr_list[0] = &h->addr;
  h->addr_list[1] = NULL;
  h->aliases = NULL;
  ret->h_name = hostname;
  ret->h_aliases = &h->aliases;
  ret->h_addrtype = AF_INET;
  ret->h_length = sizeof(ip_addr_t);
  ret->h_addr_list = (char **)&h->addr_list;
  *result = ret;
  return 0;
}

async function waitForResponse(page, baselineCount, prompt, timeoutMs) {
    const startTime = Date.now();
    let lastText = '';
    let stableCount = 0;
    while (Date.now() - startTime < timeoutMs) {
        await page.wait(3);
        let result;
        try {
            result = await page.evaluate(`(() => {
                var bubbles = document.querySelectorAll('${MESSAGE_SELECTOR}');
                var texts = Array.from(bubbles).map(function(b) {
                    var raw = (b.innerText || '').trim();
                    var parts = raw.split(/\\n\\n+/);
                    while (parts.length <= 1 && /^(Thought|View)\\b/i.test(parts[0])) parts.shift();
                    return parts.join('\\n\\n').trim();
                }).filter(Boolean);
                return {
                    count: texts.length,
                    last: texts[texts.length - 1] || '',
                    streaming: !!document.querySelector('[data-is-streaming="true"]'),
                };
            })()`);
        } catch {
            continue;
        }
        if (!result) continue;
        const candidate = result.last;
        if (!candidate || candidate === prompt.trim()) continue;
        if (result.count <= baselineCount) continue;
        if (result.streaming) {
            lastText = candidate;
            stableCount = 0;
            continue;
        }
        if (candidate === lastText) {
            stableCount++;
            if (stableCount >= 3) return candidate;
        } else {
            stableCount = 0;
            lastText = candidate;
        }
    }
    return lastText || null;
}
