int is_reserved_keyword(Token t)
{
    switch (t.type)
    {
    case TOK_TEST:
    case TOK_ASSERT:
    case TOK_SIZEOF:
    case TOK_DEF:
    case TOK_DEFER:
    case TOK_AUTOFREE:
    case TOK_USE:
    case TOK_TRAIT:
    case TOK_IMPL:
    case TOK_AND:
    case TOK_OR:
    case TOK_FOR:
    case TOK_COMPTIME:
    case TOK_UNION:
    case TOK_ASM:
    case TOK_VOLATILE:
    case TOK_ASYNC:
    case TOK_AWAIT:
    case TOK_ALIAS:
    case TOK_OPAQUE:
        return 1;
    default:
        break;
    }
    if (t.type != TOK_IDENT)
    {
        static const char *pseudo_keywords[] = {
            "let",   "var",      "static", "const",  "return", "if",    "else",   "while",
            "break", "continue", "loop",   "repeat", "unless", "guard", "launch", "do",
            "goto",  "plugin",   "fn",     "struct", "enum",   "self",  NULL};
        for (int i = 0; pseudo_keywords[i] != NULL; i++)
        {
            if (t.len == (int)strlen(pseudo_keywords[i]) &&
                strncmp(t.start, pseudo_keywords[i], t.len) == 0)
            {
                return 1;
            }
        }
    }
    return 0;
}

