err_t
tcp_rexmit(struct tcp_pcb *pcb)
{
  struct tcp_seg *seg;
  struct tcp_seg **cur_seg;
  LWIP_ASSERT("tcp_rexmit: invalid pcb", pcb != NULL);
  if (pcb->unacked == NULL) {
    return ERR_VAL;
  }
  seg = pcb->unacked;
  if (tcp_output_segment_busy(seg)) {
    LWIP_DEBUGF(TCP_RTO_DEBUG, ("tcp_rexmit busy\n"));
    return ERR_VAL;
  }
  pcb->unacked = seg->next;
  cur_seg = &(pcb->unsent);
  while (*cur_seg &&
         TCP_SEQ_LT(lwip_ntohl((*cur_seg)->tcphdr->seqno), lwip_ntohl(seg->tcphdr->seqno))) {
    cur_seg = &((*cur_seg)->next );
  }
  seg->next = *cur_seg;
  *cur_seg = seg;
#if TCP_OVERSIZE
  if (seg->next == NULL) {
    pcb->unsent_oversize = 0;
  }
#endif 
  if (pcb->nrtx < 0xFF) {
    ++pcb->nrtx;
  }
  pcb->rttest = 0;
  MIB2_STATS_INC(mib2.tcpretranssegs);
  return ERR_OK;
}

static int dfs_chan_range_available(struct hostapd_hw_modes *mode,
				    int first_chan_idx, int num_chans,
				    enum dfs_channel_type type)
{
	struct hostapd_channel_data *first_chan, *chan;
	int i;
	u32 bw = num_chan_to_bw(num_chans);
	if (first_chan_idx + num_chans > mode->num_channels) {
		wpa_printf(MSG_DEBUG,
			   "DFS: some channels in range not defined");
		return 0;
	}
	first_chan = &mode->channels[first_chan_idx];
	if (!chan_pri_allowed(first_chan)) {
		wpa_printf(MSG_DEBUG, "DFS: primary chanenl not allowed");
		return 0;
	}
	for (i = 0; i < num_chans; i++) {
		chan = dfs_get_chan_data(mode, first_chan->freq + i * 20,
					 first_chan_idx);
		if (!chan) {
			wpa_printf(MSG_DEBUG, "DFS: no channel data for %d",
				   first_chan->freq + i * 20);
			return 0;
		}
		if (!chan_bw_allowed(chan, bw, 1, !i)) {
			wpa_printf(MSG_DEBUG, "DFS: bw now allowed for %d",
				   first_chan->freq + i * 20);
			return 0;
		}
		if (!dfs_channel_available(chan, type)) {
			wpa_printf(MSG_DEBUG, "DFS: channel not available %d",
				   first_chan->freq + i * 20);
			return 0;
		}
	}
	return 1;
}

int sampler_sample(sampler_t *s, float *logits, int vocab_size) {
    if (s->temperature <= 0.0f) {
        int best = 0;
        for (int i = 1; i < vocab_size; i++) {
            if (logits[i] > logits[best]) best = i;
        }
        return best;
    }
    float inv_temp = 1.0f / s->temperature;
    for (int i = 0; i < vocab_size; i++) {
        logits[i] *= inv_temp;
    }
    softmax(logits, vocab_size);
    if (s->top_p >= 1.0f) {
        float r = rand_float(&s->rng_state);
        float cum = 0.0f;
        for (int i = 0; i < vocab_size; i++) {
            cum += logits[i];
            if (cum > r) return i;
        }
        return vocab_size - 1;
    }
    prob_index_t *sorted = (prob_index_t *)malloc((size_t)vocab_size * sizeof(prob_index_t));
    for (int i = 0; i < vocab_size; i++) {
        sorted[i].prob  = logits[i];
        sorted[i].index = i;
    }
    qsort(sorted, (size_t)vocab_size, sizeof(prob_index_t), cmp_prob_desc);
    float cum = 0.0f;
    int cutoff = 0;
    for (int i = 0; i < vocab_size; i++) {
        cum += sorted[i].prob;
        cutoff = i + 1;
        if (cum >= s->top_p) break;
    }
    float r = rand_float(&s->rng_state) * cum;
    float acc = 0.0f;
    int result = sorted[0].index;
    for (int i = 0; i < cutoff; i++) {
        acc += sorted[i].prob;
        if (acc > r) {
            result = sorted[i].index;
            break;
        }
    }
    free(sorted);
    return result;
}

static JSValue js_compile_regexp(JSContext *ctx, JSValue pattern, JSValue flags)
{
    int re_flags;
    re_flags = 0;
    if (!JS_IsUndefined(flags)) {
        JSString *ps;
        JSStringCharBuf buf;
        size_t len;
        ps = get_string_ptr(ctx, &buf, flags);
        len = js_parse_regexp_flags(&re_flags, ps->buf);
        if (len == ps->len)
            return JS_ThrowSyntaxError(ctx, "invalid regular expression flags");
    }
    return JS_Parse2(ctx, pattern, NULL, 0, "<regexp>",
                     JS_EVAL_REGEXP | (re_flags << JS_EVAL_REGEXP_FLAGS_SHIFT));
}

