function buildSearchText(worker) {
  return [
    worker.name,
    worker.description,
    worker.category,
    worker.subcategory || '',
    ...(worker.tags || []),
    ...(worker.inputs || []),
    ...(worker.outputs || []),
  ].filter(Boolean).join(' ');
}

