void gic_enable_irq(uint32_t irq)
{
    if (irq >= GIC_MAX_IRQS) {
        return;
    }
    if (irq < GIC_SPI_START) {
        uint64_t sgi_base = GICR_BASE + GICR_SGI_BASE;
        *(volatile uint32_t *)(sgi_base + GICR_ISENABLER0) = (1 << irq);
    } else {
        uint32_t reg = irq / 32;
        uint32_t bit = irq % 32;
        gicd_write(GICD_ISENABLER + reg * 4, (1 << bit));
    }
}

