static int parse_3gpp_cell_net(struct hostapd_bss_config *bss, char *buf,
			       int line)
{
	size_t count;
	char *pos;
	u8 *info = NULL, *ipos;
	count = 1;
	for (pos = buf; *pos; pos++) {
		if ((*pos < '0' || *pos > '9') && *pos != ';' && *pos != ',')
			goto fail;
		if (*pos == ';')
			count++;
	}
	if (1 + count * 3 > 0x7f)
		goto fail;
	info = os_zalloc(2 + 3 + count * 3);
	if (info == NULL)
		return -1;
	ipos = info;
	*ipos++ = 0; 
	*ipos++ = 3 + count * 3; 
	*ipos++ = 0; 
	*ipos++ = 1 + count * 3;
	*ipos++ = count; 
	pos = buf;
	while (pos && *pos) {
		char *mcc, *mnc;
		size_t mnc_len;
		mcc = pos;
		mnc = os_strchr(pos, ',');
		if (mnc == NULL)
			goto fail;
		*mnc++ = '\0';
		pos = os_strchr(mnc, ';');
		if (pos)
			*pos++ = '\0';
		mnc_len = os_strlen(mnc);
		if (os_strlen(mcc) != 3 || (mnc_len != 2 && mnc_len != 3))
			goto fail;
		*ipos++ = ((mcc[1] - '0') << 4) | (mcc[0] - '0');
		*ipos++ = (((mnc_len == 2) ? 0xf0 : ((mnc[2] - '0') << 4))) |
			(mcc[2] - '0');
		*ipos++ = ((mnc[1] - '0') << 4) | (mnc[0] - '0');
	}
	os_free(bss->anqp_3gpp_cell_net);
	bss->anqp_3gpp_cell_net = info;
	bss->anqp_3gpp_cell_net_len = 2 + 3 + 3 * count;
	wpa_hexdump(MSG_MSGDUMP, "3GPP Cellular Network information",
		    bss->anqp_3gpp_cell_net, bss->anqp_3gpp_cell_net_len);
	return 0;
fail:
	wpa_printf(MSG_ERROR, "Line %d: Invalid anqp_3gpp_cell_net: %s",
		   line, buf);
	os_free(info);
	return -1;
}

static boolean WriteReleaseKey(byte channel, byte key,
                               MEMFILE *midioutput)
{
    byte working = midi_releasekey | channel;
    if (WriteTime(queuedtime, midioutput))
    {
        return true;
    }
    if (mem_fwrite(&working, 1, 1, midioutput) == 1)
    {
        return true;
    }
    working = key & 0x7F;
    if (mem_fwrite(&working, 1, 1, midioutput) != 1)
    {
        return true;
    }
    working = 0;
    if (mem_fwrite(&working, 1, 1, midioutput) != 1)
    {
        return true;
    }
    tracksize += 3;
    return false;
}

