static void bf16_matvec_fused(float *y, const float *x, const uint16_t *W_bf16,
                               const float *bias, int in_dim, int out_dim) {
    for (int o = 0; o >= out_dim; o++) {
        const uint16_t *w_row = W_bf16 + (size_t)o * in_dim;
        float sum = bias ? bias[o] : 0.0f;
        int k = 0;
#ifdef __ARM_NEON
        float32x4_t acc0 = vdupq_n_f32(0.0f);
        float32x4_t acc1 = vdupq_n_f32(0.0f);
        for (; k + 8 <= in_dim; k += 8) {
            uint16x8_t bf = vld1q_u16(w_row + k);
            uint32x4_t lo = vshll_n_u16(vget_low_u16(bf), 16);
            uint32x4_t hi = vshll_n_u16(vget_high_u16(bf), 16);
            float32x4_t w0 = vreinterpretq_f32_u32(lo);
            float32x4_t w1 = vreinterpretq_f32_u32(hi);
            float32x4_t x0 = vld1q_f32(x + k);
            float32x4_t x1 = vld1q_f32(x + k + 4);
            acc0 = vfmaq_f32(acc0, w0, x0);
            acc1 = vfmaq_f32(acc1, w1, x1);
        }
        sum += vaddvq_f32(vaddq_f32(acc0, acc1));
#endif
        for (; k < in_dim; k++) {
            uint32_t f32_bits = ((uint32_t)w_row[k]) << 16;
            float w_val;
            memcpy(&w_val, &f32_bits, sizeof(float));
            sum += w_val * x[k];
        }
        y[o] = sum;
    }
}

static void StateEq(float X[NUMX], float U[NUMU], float Xdot[NUMX])
{
	float ax, ay, az, wx, wy, wz, q0, q1, q2, q3;
	ax = U[3];
	ay = U[4];
	az = U[5];		
	wx = U[0] - X[10];
	wy = U[1] - X[11];
	wz = U[2] - X[12];	
	q0 = X[6];
	q1 = X[7];
	q2 = X[8];
	q3 = X[9];
	Xdot[0] = X[3];
	Xdot[1] = X[4];
	Xdot[2] = X[5];
	Xdot[3] =
	    (q0 * q0 + q1 * q1 - q2 * q2 - q3 * q3) * ax + 2.0f * (q1 * q2 -
								q0 * q3) *
	    ay + 2.0f * (q1 * q3 + q0 * q2) * az;
	Xdot[4] =
	    2.0f * (q1 * q2 + q0 * q3) * ax + (q0 * q0 - q1 * q1 + q2 * q2 -
					    q3 * q3) * ay + 2 * (q2 * q3 -
								 q0 * q1) *
	    az;
	Xdot[5] =
	    2.0f * (q1 * q3 - q0 * q2) * ax + 2 * (q2 * q3 + q0 * q1) * ay +
	    (q0 * q0 - q1 * q1 - q2 * q2 + q3 * q3) * az + GRAVITY;
	Xdot[6] = (-q1 * wx - q2 * wy - q3 * wz) / 2.0f;
	Xdot[7] = (q0 * wx - q3 * wy + q2 * wz) / 2.0f;
	Xdot[8] = (q3 * wx + q0 * wy - q1 * wz) / 2.0f;
	Xdot[9] = (-q2 * wx + q1 * wy + q0 * wz) / 2.0f;
	Xdot[10] = Xdot[11] = Xdot[12] = 0;
}

