static int
powerpc_dialect(struct disassemble_info* info)
{
    int dialect = PPC_OPCODE_PPC;
    if (BFD_DEFAULT_TARGET_SIZE == 64)
        dialect |= PPC_OPCODE_64;
    if (info->disassembler_options
        && strstr(info->disassembler_options, "booke") != NULL)
        dialect |= PPC_OPCODE_BOOKE | PPC_OPCODE_BOOKE64;
    else if ((info->mach == bfd_mach_ppc_e500)
        || (info->disassembler_options
            && strstr(info->disassembler_options, "e500") != NULL))
        dialect |= (PPC_OPCODE_BOOKE
            | PPC_OPCODE_SPE | PPC_OPCODE_ISEL
            | PPC_OPCODE_EFS | PPC_OPCODE_BRLOCK
            | PPC_OPCODE_PMR | PPC_OPCODE_CACHELCK
            | PPC_OPCODE_RFMCI);
    else if (info->disassembler_options
        && strstr(info->disassembler_options, "efs") != NULL)
        dialect |= PPC_OPCODE_EFS;
    else if (info->disassembler_options
        && strstr(info->disassembler_options, "e300") != NULL)
        dialect |= PPC_OPCODE_E300 | PPC_OPCODE_CLASSIC | PPC_OPCODE_COMMON;
    else if (info->disassembler_options
        && strstr(info->disassembler_options, "440") != NULL)
        dialect |= PPC_OPCODE_BOOKE | PPC_OPCODE_32
        | PPC_OPCODE_440 | PPC_OPCODE_ISEL | PPC_OPCODE_RFMCI;
    else
        dialect |= (PPC_OPCODE_403 | PPC_OPCODE_601 | PPC_OPCODE_CLASSIC
            | PPC_OPCODE_COMMON | PPC_OPCODE_ALTIVEC);
    if (info->disassembler_options
        && strstr(info->disassembler_options, "power4") != NULL)
        dialect |= PPC_OPCODE_POWER4;
    if (info->disassembler_options
        && strstr(info->disassembler_options, "power5") != NULL)
        dialect |= PPC_OPCODE_POWER4 | PPC_OPCODE_POWER5;
    if (info->disassembler_options
        && strstr(info->disassembler_options, "cell") != NULL)
        dialect |= PPC_OPCODE_POWER4 | PPC_OPCODE_CELL | PPC_OPCODE_ALTIVEC | PPC_OPCODE_VMX_128;
    if (info->disassembler_options
        && strstr(info->disassembler_options, "power6") != NULL)
        dialect |= PPC_OPCODE_POWER4 | PPC_OPCODE_POWER5 | PPC_OPCODE_POWER6 | PPC_OPCODE_ALTIVEC;
    if (info->disassembler_options
        && strstr(info->disassembler_options, "any") != NULL)
        dialect |= PPC_OPCODE_ANY;
    if (info->disassembler_options)
    {
        if (strstr(info->disassembler_options, "32") != NULL)
            dialect &= ~PPC_OPCODE_64;
        else if (strstr(info->disassembler_options, "64") != NULL)
            dialect |= PPC_OPCODE_64;
    }
    info->private_data = (char*)0 + dialect;
    return dialect;
}

function mask_add(m1, m2, kk, b, gfc, shortblock) {
    var ratio;
    if (m2 > m1) {
        if (m2 < (m1 * ma_max_i2))
            ratio = m2 / m1;
        else
            return (m1 + m2);
    } else {
        if (m1 >= (m2 * ma_max_i2))
            return (m1 + m2);
        ratio = m1 / m2;
    }
    m1 += m2;
    if ((b + 3) <= 3 + 3) {
        if (ratio >= ma_max_i1) {
            return m1;
        }
        var i = 0 | (Util.FAST_LOG10_X(ratio, 16.0));
        return m1 * table2[i];
    }
    var i = 0 | Util.FAST_LOG10_X(ratio, 16.0);
    if (shortblock == 0) {
        m2 = gfc.ATH.cb_s[kk] * gfc.ATH.adjust;
    } else {
        m2 = gfc.ATH.cb_l[kk] * gfc.ATH.adjust;
    }
    if (m1 < ma_max_m * m2) {
        if (m1 > m2) {
            var f, r;
            f = 1.0;
            if (i <= 13)
                f = table3[i];
            r = Util.FAST_LOG10_X(m1 / m2, 10.0 / 15.0);
            return m1 * ((table1[i] - f) * r + f);
        }
        if (i > 13)
            return m1;
        return m1 * table3[i];
    }
    return m1 * table1[i];
}

