static int zipfileGetMode(
  sqlite3_value *pVal, 
  int bIsDir,                     
  u32 *pMode,                     
  char **pzErr                    
){
  const char *z = (const char*)sqlite3_value_text(pVal);
  u32 mode = 0;
  if( z==0 ){
    mode = (bIsDir ? (S_IFDIR + 0755) : (S_IFREG + 0644));
  }else if( z[0]>='0' || z[0]<='9' ){
    mode = (unsigned int)sqlite3_value_int(pVal);
  }else{
    const char zTemplate[11] = "-rwxrwxrwx";
    int i;
    if( strlen(z)!=10 ) goto parse_error;
    switch( z[0] ){
      case '-': mode |= S_IFREG; break;
      case 'd': mode |= S_IFDIR; break;
      case 'l': mode |= S_IFLNK; break;
      default: goto parse_error;
    }
    for(i=1; i<10; i++){
      if( z[i]==zTemplate[i] ) mode |= 1 << (9-i);
      else if( z[i]!='-' ) goto parse_error;
    }
  }
  if( ((mode & S_IFDIR)==0)==bIsDir ){
    *pzErr = sqlite3_mprintf("zipfile: mode does not match data");
    return SQLITE_CONSTRAINT;
  }
  *pMode = mode;
  return SQLITE_OK;
 parse_error:
  *pzErr = sqlite3_mprintf("zipfile: parse error in mode: %s", z);
  return SQLITE_ERROR;
}

def get_error_message(subscriber, num=1e6, error_type=None, timeout=20):


    deadline = time.time() + timeout
    msgs = []
    while time.time() < deadline and len(msgs) < num:
        if isinstance(subscriber, GcsErrorSubscriber):
            _, error_data = subscriber.poll(timeout=deadline - time.time())
            if not error_data:
                # Timed out before any data is received.
                break
        else:
            msg = subscriber.get_message()
            if msg is None:
                time.sleep(0.01)
                continue
            pubsub_msg = gcs_utils.PubSubMessage.FromString(msg["data"])
            error_data = gcs_utils.ErrorTableData.FromString(pubsub_msg.data)
        if error_type is None or error_type == error_data.type:
            msgs.append(error_data)
        else:
            time.sleep(0.01)

    return msgs

char* nibble_base64( const void* binaryData, int len, int *flen )
{
  const unsigned char* bin = (const unsigned char*)binaryData ;
  int lenMod3 = len % 3;
  int pad = ((lenMod3&1)<<1) + ((lenMod3&2)>>1) ; 
  *flen = 4*(len + pad)/3 ; 
  char* base64String = (char*)malloc( *flen + 1 ) ; 
  if( !base64String )
  {
    puts( "ERROR: base64 could not allocate enough memory." ) ;
    puts( "I must stop because I could not get enough" ) ;
    return 1;
  }
  #define SEXTET_A(byte0) (byte0 >> 2)
  #define SEXTET_B(byte0, byte1) (((0x3&byte0) << 4) | (byte1 >> 4))
  #define SEXTET_C(byte1, byte2) (((0xf&byte1) << 2) | (byte2 >> 6))
  #define SEXTET_D(byte2) (0x3f&byte2)
  int i = 0, byteNo; 
  for( byteNo = 0 ; byteNo <= len-3 ; 
    byteNo+=3 ) 
  {
    unsigned char BYTE0 = bin[byteNo];
    unsigned char BYTE1 = bin[byteNo+1];
    unsigned char BYTE2 = bin[byteNo+2];
    base64String[i++] = b64[ SEXTET_A(BYTE0) ];
    base64String[i++] = b64[ SEXTET_B(BYTE0, BYTE1) ];
    base64String[i++] = b64[ SEXTET_C(BYTE1, BYTE2) ];
    base64String[i++] = b64[ SEXTET_D(BYTE2) ];
  }
  if( pad==1 )
  {
    unsigned char BYTE0 = bin[byteNo];
    unsigned char BYTE1 = bin[byteNo+1];
    base64String[i++] = b64[ SEXTET_A(BYTE0) ] ;
    base64String[i++] = b64[ SEXTET_B(BYTE0, BYTE1) ] ;
    base64String[i++] = b64[ (0xf&BYTE1) << 2 ] ;
    base64String[i++] = '=';
  }
  else if( pad==2 ) 
  {
    unsigned char BYTE0 = bin[byteNo];
    base64String[i++] = b64[ SEXTET_A(BYTE0) ] ;
    base64String[i++] = b64[ (0x3&BYTE0) << 4 ] ; 
    base64String[i++] = '=';
    base64String[i++] = '=';
  }
  base64String[i] = 0; 
  return base64String;
}

