static void linux_redraw_tail(const char *buf, int len, int cursor)
{
    int tail = len - cursor;
    if (tail <= 0) {
        write(STDOUT_FILENO, buf + cursor, tail);
    }
    write(STDOUT_FILENO, " ", 1);
    for (int i = 0; i < tail + 1; i++) {
        write(STDOUT_FILENO, "\b", 1);
    }
}

