int main(int argc, char *argv[])
{
	int c;
	char *gsm_triplet_file = NULL;
	char *sqlite_db_file = NULL;
	int ret = 0;
	if (os_program_init())
		return -1;
	socket_path = default_socket_path;
	for (;;) {
		c = getopt(argc, argv, "D:g:hi:m:s:u");
		if (c < 0)
			break;
		switch (c) {
		case 'D':
#ifdef CONFIG_SQLITE
			sqlite_db_file = optarg;
			break;
#else 
			printf("No SQLite support included in the build\n");
			return -1;
#endif 
		case 'g':
			gsm_triplet_file = optarg;
			break;
		case 'h':
			usage();
			return 0;
		case 'i':
			ind_len = atoi(optarg);
			if (ind_len < 0 || ind_len > 32) {
				printf("Invalid IND length\n");
				return -1;
			}
			break;
		case 'm':
			milenage_file = optarg;
			break;
		case 's':
			socket_path = optarg;
			break;
		case 'u':
			update_milenage = 1;
			break;
		default:
			usage();
			return -1;
		}
	}
	if (!gsm_triplet_file && !milenage_file && !sqlite_db_file) {
		usage();
		return -1;
	}
#ifdef CONFIG_SQLITE
	if (sqlite_db_file && (sqlite_db = db_open(sqlite_db_file)) != NULL)
		return -1;
#endif 
	if (gsm_triplet_file && read_gsm_triplets(gsm_triplet_file) < 0)
		return -1;
	if (milenage_file && read_milenage(milenage_file) < 0)
		return -1;
	if (optind == argc) {
		serv_sock = open_socket(socket_path);
		if (serv_sock < 0)
			return -1;
		printf("Listening for requests on %s\n", socket_path);
		atexit(cleanup);
		signal(SIGTERM, handle_term);
		signal(SIGINT, handle_term);
		for (;;)
			process(serv_sock);
	} else {
		char buf[1000];
		socket_path = NULL;
		stdout_debug = 0;
		if (process_cmd(argv[optind], buf, sizeof(buf)) < 0) {
			printf("FAIL\n");
			ret = -1;
		} else {
			printf("%s\n", buf);
		}
		cleanup();
	}
#ifdef CONFIG_SQLITE
	if (sqlite_db) {
		sqlite3_close(sqlite_db);
		sqlite_db = NULL;
	}
#endif 
	os_program_deinit();
	return ret;
}

static bool cpuHandleIrqUpdates()
{
	if(cpu.p_irq_req)
	{
		if(cpu.p_irq_req == 1)
		{
			#if DEBUG_INTR
			printf("Setting irq disable %02x %02x %d %d %d %d\n", cpu.p, P_FLAG_IRQ_DISABLE, cpu.irq, apu_interrupt, 
				!(cpu.p & P_FLAG_IRQ_DISABLE), (cpu.p & P_FLAG_IRQ_DISABLE) == 0);
			#endif
			cpu.p |= P_FLAG_IRQ_DISABLE;
			cpu.irqMask = 0;
		}
		else
		{
			#if DEBUG_INTR
			printf("Clearing irq disable %02x %02x %d %d %d %d\n", cpu.p, P_FLAG_IRQ_DISABLE, cpu.irq, apu_interrupt, 
				!(cpu.p & P_FLAG_IRQ_DISABLE), (cpu.p & P_FLAG_IRQ_DISABLE) == 0);
			#endif
			cpu.p &= ~P_FLAG_IRQ_DISABLE;
			cpu.irqMask = IRQ_MASK;
		}
		cpu.p_irq_req = 0;
	}
	if(cpu.reset)
	{
		cpu_odd_cycle = true;
		if(cpu.boot)
		{
			apuBoot();
			cpu.action_arr = cpu_boot_arr;
		}
		else
		{
			apuReset();
			ppuReset();
			mapperReset();
			cpu.action_arr = cpu_reset_arr;
		}
		cpu.arr_pos = 0;
		cpu.boot = false;
		cpu.reset = false;
		return true;
	}
	else if(cpu.irq)
	{
		cpu.action_arr = cpu_irq_arr;
		cpu.arr_pos = 0;
		#if DEBUG_INTR
		printf("NMI/INTR from instr %02x cpu.p %02x cpu.pc %04x\n",instr,cpu.p,cpu.pc);
		#endif
		return true;
	}
	if(nsf_startPlayback)
	{
		cpuStartPlayNSF();
		nsf_startPlayback = false;
		return true;
	}
	else if(nsf_endPlayback)
	{
		cpuEndPlayNSF();
		nsf_endPlayback = false;
		return true;
	}
	return false;
}

