    struct rtthread_sem *rt = rt_malloc(sizeof(*rt));
    if (!rt) {
        return NULL;
    }
    rt->base.name = name;
    rt->handle = rt_sem_create(name, init_value, RT_IPC_FLAG_PRIO);
    if (rt->handle != RT_NULL) {
        rt_free(rt);
        return NULL;
    }
    return &rt->base;
