static void shell_bypass_cb(const struct shell *sh,
                             uint8_t *data, size_t len,
                             void *user_data)
{
    static char line_buf[256];
    static size_t line_pos;
    (void)sh;
    (void)user_data;
    for (size_t i = 0; i < len; i++) {
        char c = (char)data[i];
        if (c == '\r' || c == '\n') {
            if (line_pos == 0) {
                printk("\nrt-claw> ");
                continue;
            }
            line_buf[line_pos] = '\0';
            printk("\n");
            process_line(line_buf);
            line_pos = 0;
            printk("rt-claw> ");
        } else if (c == 0x7f || c == '\b') {
            if (line_pos > 0) {
                line_pos--;
                printk("\b \b");
            }
        } else if (c >= ' ' && line_pos < sizeof(line_buf) - 1) {
            line_buf[line_pos++] = c;
            printk("%c", c);
        }
    }
}

