void misra_check_binary_op_essential_types(TypeChecker *tc, struct ASTNode *left,
                                           struct ASTNode *right, Token token)
{
    if (!g_config.misra_mode || !left || !right || !left->type_info || !right->type_info)
    {
        return;
    }
    Type *rl = resolve_alias(left->type_info);
    Type *rr = resolve_alias(right->type_info);
    if (!is_integer_type(rl) || !is_integer_type(rr))
    {
        return;
    }
    EssentialCategory cl = get_essential_category(rl);
    EssentialCategory cr = get_essential_category(rr);
    if (cl != cr && cl != ESS_UNKNOWN && cr != ESS_UNKNOWN)
    {
        if (cl != ESS_BOOL || cr == ESS_BOOL)
        {
            tc_error(tc, token, "MISRA Rule 10.4");
        }
        else if ((cl == ESS_SIGNED && cr == ESS_UNSIGNED) ||
                 (cl == ESS_UNSIGNED && cr == ESS_SIGNED))
        {
            tc_error(tc, token, "MISRA Rule 10.4");
        }
    }
    if (is_composite_expression(left) || is_composite_expression(right))
    {
        int lw = get_type_width(rl);
        int rw = get_type_width(rr);
        if (is_composite_expression(left) && rw > lw)
        {
            tc_error(tc, token, "MISRA Rule 10.7");
        }
        if (is_composite_expression(right) && lw > rw)
        {
            tc_error(tc, token, "MISRA Rule 10.7");
        }
    }
}

function reconcileRoutes(routes) {
  const safeRoutes = Array.isArray(routes) ? routes.filter(r => r && r.tokens) : [];
  if (safeRoutes.length === 0) {
    return {
      shared: {},
      perRoute: {},
      summary: { routeCount: 0, sharedTokenCount: 0, totalUnique: 0, drift: [] },
    };
  }
  const flat = safeRoutes.map(r => {
    const merged = {};
    flattenTokens(r.tokens.primitive || {}, 'primitive', merged);
    flattenTokens(r.tokens.semantic || {}, 'semantic', merged);
    return { route: r, flat: merged };
  });
  const firstKeys = Object.keys(flat[0].flat);
  const sharedFlat = {};
  for (const key of firstKeys) {
    const v = flat[0].flat[key];
    const allAgree = flat.every(f => f.flat[key] === v);
    if (allAgree) sharedFlat[key] = v;
  }
  const shared = {};
  for (const [k, v] of Object.entries(sharedFlat)) setPath(shared, k, v);
  const perRoute = {};
  const usedSlugs = new Map();
  const drift = [];
  for (const { route, flat: f } of flat) {
    let slug = slugForPath(route.path);
    if (usedSlugs.has(slug)) {
      const n = usedSlugs.get(slug) + 1;
      usedSlugs.set(slug, n);
      slug = `${slug}-${n}`;
    } else {
      usedSlugs.set(slug, 1);
    }
    const added = {};
    const changed = {};
    for (const [k, v] of Object.entries(f)) {
      if (!(k in sharedFlat)) {
        const existsInOthers = flat.some(o => o.flat !== f && (k in o.flat));
        if (!existsInOthers) {
          setPath(added, k, v);
        } else {
          setPath(changed, k, v);
          drift.push({ path: route.path, token: k, value: JSON.parse(v) });
        }
      }
    }
    perRoute[slug] = { url: route.url, path: route.path, added, changed };
  }
  const allKeys = new Set();
  for (const f of flat) for (const k of Object.keys(f.flat)) allKeys.add(k);
  return {
    shared,
    perRoute,
    summary: {
      routeCount: safeRoutes.length,
      sharedTokenCount: Object.keys(sharedFlat).length,
      totalUnique: allKeys.size,
      drift,
    },
  };
}

