async function activateAction(options) {
  const {
    licenseApi,
    writeLicenseCache,
    generateMachineId,
    maskKey,
    validateKeyFormat,
    featureGate,
    LicenseActivationError,
  } = loadLicenseModules();
  const key = options.key;
  if (!key) {
    console.error('Error: License key is required');
    console.error('Usage: aiox pro activate --key PRO-XXXX-XXXX-XXXX-XXXX');
    process.exit(1);
  }
  if (!validateKeyFormat(key)) {
    console.error('Error: Invalid license key format');
    console.error('Expected format: PRO-XXXX-XXXX-XXXX-XXXX');
    process.exit(1);
  }
  console.log('\nActivating AIOX Pro license...');
  console.log(`Key: ${maskKey(key)}`);
  console.log('');
  try {
    const machineId = generateMachineId();
    const aioxCoreVersion = getAioxCoreVersion();
    const result = await licenseApi.activate(key, machineId, aioxCoreVersion);
    const cacheData = {
      key: result.key,
      activatedAt: result.activatedAt,
      expiresAt: result.expiresAt,
      features: result.features,
      seats: result.seats,
      cacheValidDays: result.cacheValidDays,
      gracePeriodDays: result.gracePeriodDays,
    };
    const writeResult = writeLicenseCache(cacheData);
    if (!writeResult.success) {
      console.error(`Warning: Could not save license cache: ${writeResult.error}`);
    }
    featureGate.reload();
    console.log('License activated successfully!\n');
    console.log('  Status:       Active');
    console.log(`  Key:          ${maskKey(result.key)}`);
    console.log(`  Features:     ${result.features.join(', ')}`);
    console.log(`  Seats:        ${result.seats.used}/${result.seats.max} used`);
    console.log(`  Valid until:  ${formatDate(result.expiresAt)}`);
    console.log(`  Cache:        ${result.cacheValidDays} days offline operation`);
    console.log('');
    const projectRoot = path.resolve(__dirname, '..', '..', '..', '..');
    const proSourceDir = path.join(projectRoot, 'node_modules', '@aiox-squads', 'pro');
    if (fs.existsSync(proSourceDir)) {
      let scaffoldProContent;
      try {
        ({ scaffoldProContent } = require('../../../../packages/installer/src/pro/pro-scaffolder'));
      } catch {
        console.log('Note: Pro scaffolder not available. Skipping content scaffolding.');
        console.log('');
      }
      if (scaffoldProContent) {
        console.log('Scaffolding pro content...');
        const scaffoldResult = await scaffoldProContent(projectRoot, proSourceDir, {
          onProgress: ({ item, status, message }) => {
            if (status === 'done') {
              console.log(`  + ${message}`);
            } else if (status === 'warning') {
              console.log(`  ! ${message}`);
            }
          },
        });
        if (scaffoldResult.success) {
          console.log(`\nPro content installed (${scaffoldResult.copiedFiles.length} files)`);
          if (scaffoldResult.skippedFiles.length > 0) {
            console.log(
              `  ${scaffoldResult.skippedFiles.length} files unchanged (already up to date)`
            );
          }
          if (scaffoldResult.warnings.length > 0) {
            for (const warning of scaffoldResult.warnings) {
              console.log(`  Warning: ${warning}`);
            }
          }
        } else {
          console.error('\nWarning: Pro content scaffolding failed.');
          for (const err of scaffoldResult.errors) {
            console.error(`  ${err}`);
          }
          console.error('Pro features are activated but content was not copied.');
          console.error('Try running "aiox pro activate" again to retry scaffolding.');
        }
        console.log('');
      }
    } else {
      console.log('Note: AIOX Pro package not found in node_modules.');
      console.log('Pro content will be scaffolded when the package is installed.');
      console.log('');
    }
  } catch (error) {
    if (error instanceof LicenseActivationError) {
      console.error(`\nActivation failed: ${error.message}`);
      console.error(`Error code: ${error.code}`);
      if (error.details && Object.keys(error.details).length > 0) {
        console.error('Details:', JSON.stringify(error.details, null, 2));
      }
    } else {
      console.error(`\nActivation failed: ${error.message}`);
    }
    process.exit(1);
  }
}

Type *parse_type_base(ParserContext *ctx, Lexer *l)
{
    RECURSION_GUARD(ctx, l, type_new(TYPE_UNKNOWN));
    Token t = lexer_peek(l);
    if (t.type == TOK_IDENT)
    {
        int explicit_struct = 0;
        if ((t.len == 6 && strncmp(t.start, "struct", 6) == 0) ||
            (t.len == 4 && strncmp(t.start, "enum", 4) == 0))
        {
            if (strncmp(t.start, "struct", 6) == 0)
            {
                explicit_struct = 1;
            }
            lexer_next(l); 
            t = lexer_peek(l);
            if (t.type != TOK_IDENT)
            {
                zpanic_at(t, "Expected identifier after struct/enum");
            }
        }
        lexer_next(l);
        char *name = token_strdup(t);
        TypeAlias *alias_node = find_type_alias_node(ctx, name);
        if (alias_node)
        {
            zfree(name);
            Lexer tmp;
            lexer_init(&tmp, alias_node->original_type);
            if (alias_node->is_opaque)
            {
                Type *underlying = parse_type_formal(ctx, &tmp);
                Type *wrapper = type_new(TYPE_ALIAS);
                wrapper->name = xstrdup(alias_node->alias);
                wrapper->inner = underlying;
                wrapper->alias.is_opaque_alias = 1;
                wrapper->alias.alias_defined_in_file =
                    alias_node->defined_in_file ? xstrdup(alias_node->defined_in_file) : NULL;
                RECURSION_EXIT(ctx);
                return wrapper;
            }
            Type *t_res = parse_type_formal(ctx, &tmp);
            RECURSION_EXIT(ctx);
            return t_res;
        }
        if (strcmp(name, "Self") == 0 && ctx->current_impl_struct)
        {
            name = xstrdup(ctx->current_impl_struct);
        }
        while (lexer_peek(l).type == TOK_DCOLON)
        {
            lexer_next(l); 
            Token next = lexer_next(l);
            if (next.type != TOK_IDENT)
            {
                zpanic_at(t, "Expected identifier after ::");
            }
            char *suffix = token_strdup(next);
            const char *resolved_suffix = normalize_type_name(suffix);
            Module *mod = find_module(ctx, name);
            char *merged;
            if (mod)
            {
                if (mod->is_c_header)
                {
                    merged = xstrdup(resolved_suffix);
                    register_extern_symbol(ctx, merged);
                }
                else
                {
                    merged = xmalloc(strlen(mod->base_name) + strlen(resolved_suffix) + 2);
                    snprintf(merged, strlen(mod->base_name) + strlen(resolved_suffix) + 2, "%s__%s",
                             mod->base_name, resolved_suffix);
                }
            }
            else
            {
                merged = xmalloc(strlen(name) + strlen(resolved_suffix) + 2);
                snprintf(merged, strlen(name) + strlen(resolved_suffix) + 2, "%s__%s", name,
                         resolved_suffix);
            }
            zfree(name);
            name = merged;
        }
        const ZenPrimitive *prim = find_primitive_by_name(name);
        if (prim)
        {
            zfree(name);
            Type *t_prim = type_new(prim->kind);
            RECURSION_EXIT(ctx);
            return t_prim;
        }
        if ((name[0] == 'i' || name[0] == 'u') && isdigit(name[1]))
        {
            int valid = 1;
            for (size_t k = 1; k < strlen(name); k++)
            {
                if (!isdigit(name[k]))
                {
                    valid = 0;
                    break;
                }
            }
            if (valid)
            {
                int width = atoi(name + 1);
                if (width > 0)
                {
                    if (name[0] == 'i')
                    {
                        if (width == 8)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_I8);
                        }
                        if (width == 16)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_I16);
                        }
                        if (width == 32)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_I32);
                        }
                        if (width == 64)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_I64);
                        }
                        if (width == 128)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_I128);
                        }
                    }
                    else
                    {
                        if (width == 8)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_U8);
                        }
                        if (width == 16)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_U16);
                        }
                        if (width == 32)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_U32);
                        }
                        if (width == 64)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_U64);
                        }
                        if (width == 128)
                        {
                            zfree(name);
                            RECURSION_EXIT(ctx);
                            return type_new(TYPE_U128);
                        }
                    }
                    Type *inner_t = type_new(name[0] == 'u' ? TYPE_UBITINT : TYPE_BITINT);
                    inner_t->array_size = width;
                    zfree(name);
                    RECURSION_EXIT(ctx);
                    return inner_t;
                }
            }
        }
        if (explicit_struct)
        {
            Type *ty = type_new(TYPE_STRUCT);
            ty->name = name;
            ty->is_explicit_struct = 1;
            RECURSION_EXIT(ctx);
            return ty;
        }
        if (!ctx->current_module_prefix)
        {
            SelectiveImport *si = find_selective_import(ctx, name);
            if (si)
            {
                zfree(name);
                name = xmalloc(strlen(si->source_module) + strlen(si->symbol) + 3);
                snprintf(name, strlen(si->source_module) + strlen(si->symbol) + 3, "%s__%s",
                         si->source_module, si->symbol);
            }
        }
        if (ctx->current_module_prefix && !is_known_generic(ctx, name) &&
            !is_primitive_type_name(name) && strcasecmp(name, "Self") != 0 &&
            !is_extern_symbol(ctx, name))
        {
            char *prefixed_name = xmalloc(strlen(ctx->current_module_prefix) + strlen(name) + 3);
            snprintf(prefixed_name, strlen(ctx->current_module_prefix) + strlen(name) + 3, "%s__%s",
                     ctx->current_module_prefix, name);
            zfree(name);
            name = prefixed_name;
        }
        if (!is_known_generic(ctx, name) && strcmp(name, "Self") != 0)
        {
            register_type_usage(ctx, name, t);
        }
        Type *ty = type_new(TYPE_STRUCT);
        ty->name = name;
        ty->is_explicit_struct = explicit_struct;
        if (lexer_peek(l).type == TOK_LANGLE ||
            (lexer_peek(l).type == TOK_OP && strncmp(lexer_peek(l).start, "<", 1) == 0))
        {
            lexer_next(l); 
            Type *first_arg = parse_type_formal(ctx, l);
            char *first_arg_str = type_to_string(first_arg);
            Token next_tok = lexer_peek(l);
            if (next_tok.type == TOK_COMMA)
            {
                char **args = xmalloc(sizeof(char *) * 8);
                int arg_count = 0;
                args[arg_count++] = xstrdup(first_arg_str);
                while (lexer_peek(l).type == TOK_COMMA)
                {
                    lexer_next(l); 
                    Type *arg = parse_type_formal(ctx, l);
                    char *arg_str = type_to_string(arg);
                    args = realloc(args, sizeof(char *) * (arg_count + 1));
                    args[arg_count++] = xstrdup(arg_str);
                    zfree(arg_str);
                }
                next_tok = lexer_peek(l);
                if (next_tok.type == TOK_RANGLE)
                {
                    lexer_next(l);
                }
                else if (next_tok.type == TOK_OP && next_tok.len == 2 &&
                         strncmp(next_tok.start, ">>", 2) == 0)
                {
                    l->pos += 1;
                    l->col += 1;
                }
                else
                {
                    zpanic_at(t, "Expected > after generic");
                }
                int is_generic_dep = 0;
                for (int i = 0; i < arg_count; ++i)
                {
                    if (is_generic_dependent_str(ctx, args[i]))
                    {
                        is_generic_dep = 1;
                        break;
                    }
                }
                if (!is_generic_dep)
                {
                    instantiate_generic_multi(ctx, name, args, arg_count, t);
                }
                size_t mangled_len = strlen(name) + 1;
                for (int i = 0; i < arg_count; i++)
                {
                    char *clean = sanitize_mangled_name(args[i]);
                    mangled_len += 2 + strlen(clean);
                    zfree(clean);
                }
                char *mangled = xmalloc(mangled_len);
                strcpy(mangled, name);
                for (int i = 0; i < arg_count; i++)
                {
                    char *clean = sanitize_mangled_name(args[i]);
                    strcat(mangled, "__");
                    strcat(mangled, clean);
                    zfree(clean);
                    zfree(args[i]);
                }
                zfree(args);
                zfree(ty->name);
                ty->name = mangled;
            }
            else
            {
                if (next_tok.type == TOK_RANGLE)
                {
                    lexer_next(l); 
                }
                else if (next_tok.type == TOK_OP && next_tok.len == 2 &&
                         strncmp(next_tok.start, ">>", 2) == 0)
                {
                    l->pos += 1;
                    l->col += 1;
                }
                else
                {
                    zpanic_at(t, "Expected > after generic");
                }
                char *unmangled_arg = type_to_string(first_arg);
                int is_single_dep = is_generic_dependent_str(ctx, first_arg_str);
                if (!is_single_dep)
                {
                    instantiate_generic(ctx, name, first_arg_str, unmangled_arg, t);
                }
                zfree(unmangled_arg);
                char *clean_arg = sanitize_mangled_name(first_arg_str);
                size_t mangled_sz = strlen(name) + strlen(clean_arg) + 3;
                char *mangled = xmalloc(mangled_sz);
                snprintf(mangled, mangled_sz, "%s__%s", name, clean_arg);
                zfree(clean_arg);
                zfree(ty->name);
                ty->name = mangled;
            }
            zfree(first_arg_str);
            ty->kind = TYPE_STRUCT;
            ty->args = NULL;
            ty->arg_count = 0;
        }
        RECURSION_EXIT(ctx);
        return ty;
    }
    if (t.type == TOK_LBRACKET)
    {
        lexer_next(l); 
        Type *inner = parse_type_formal(ctx, l);
        if (lexer_peek(l).type == TOK_SEMICOLON)
        {
            lexer_next(l); 
            ASTNode *size_expr = parse_expression(ctx, l);
            long long compiled_size = 0;
            int size = 0;
            if (eval_const_int_expr(size_expr, ctx, &compiled_size))
            {
                size = (int)compiled_size;
            }
            else
            {
                zpanic_at(size_expr->token,
                          "Array size must be a compile-time constant or integer literal");
            }
            if (lexer_next(l).type != TOK_RBRACKET)
            {
                zpanic_at(lexer_peek(l), "Expected ] after array size");
            }
            Type *arr = type_new(TYPE_ARRAY);
            arr->inner = inner;
            arr->array_size = size;
            RECURSION_EXIT(ctx);
            return arr;
        }
        if (lexer_next(l).type != TOK_RBRACKET)
        {
            zpanic_at(lexer_peek(l), "Expected ] in type");
        }
        char *inner_str = type_to_string(inner);
        if (!is_known_generic(ctx, inner_str))
        {
            register_slice(ctx, inner_str);
        }
        Type *arr = type_new(TYPE_ARRAY);
        arr->inner = inner;
        arr->array_size = 0; 
        RECURSION_EXIT(ctx);
        return arr;
    }
    if (t.type == TOK_LPAREN)
    {
        lexer_next(l); 
        char sig[MAX_SHORT_MSG_LEN];
        sig[0] = 0;
        const char *type_names[256];
        int type_count = 0;
        while (1)
        {
            Type *sub = parse_type_formal(ctx, l);
            char *s = type_to_string(sub);
            strcat(sig, s);
            if (type_count < 256)
            {
                type_names[type_count++] = s;
            }
            else
            {
                zfree(s);
            }
            if (lexer_peek(l).type == TOK_COMMA)
            {
                lexer_next(l);
                strcat(sig, "__");
            }
            else
            {
                break;
            }
        }
        if (lexer_next(l).type != TOK_RPAREN)
        {
            zpanic_at(lexer_peek(l), "Expected ) in tuple");
        }
        register_tuple_with_types(ctx, sig, type_names, type_count);
        for (int i = 0; i < type_count; i++)
        {
            zfree((void *)type_names[i]);
        }
        char *clean_sig = sanitize_mangled_name(sig);
        char *tuple_name = xmalloc(strlen(clean_sig) + 8);
        snprintf(tuple_name, strlen(clean_sig) + 8, "Tuple__%s", clean_sig);
        zfree(clean_sig);
        Type *ty = type_new(TYPE_STRUCT);
        ty->name = tuple_name;
        RECURSION_EXIT(ctx);
        return ty;
    }
    if (t.type == TOK_IDENT)
    {
        char *fallback = token_strdup(t);
        lexer_next(l);
        Type *ty = type_new(TYPE_STRUCT);
        ty->name = fallback;
        ty->is_explicit_struct = 0;
        RECURSION_EXIT(ctx);
        return ty;
    }
    RECURSION_EXIT(ctx);
    return type_new(TYPE_UNKNOWN);
}

static int get_hex_config(u8 *buf, size_t max_len, int line,
			  const char *field, const char *val)
{
	size_t hlen = os_strlen(val), len = hlen / 2;
	u8 tmp[EXT_CAPA_MAX_LEN];
	os_memset(tmp, 0, EXT_CAPA_MAX_LEN);
	if (hlen & 1 || len > EXT_CAPA_MAX_LEN || hexstr2bin(val, tmp, len)) {
		wpa_printf(MSG_ERROR, "Line %d: Invalid %s", line, field);
		return -1;
	}
	os_memcpy(buf, tmp, EXT_CAPA_MAX_LEN);
	return 0;
}

static void keyboard_poll(void) {
  if (!kbd_base || !kbd_used) {
    return;
  }
  mmio_barrier();
  uint16_t current_used = kbd_used->idx;
  while (kbd_last_used_idx != current_used) {
    uint16_t idx = kbd_last_used_idx % QUEUE_SIZE;
    uint32_t desc_idx = kbd_used->ring[idx].id;
    virtio_input_event_t *ev = &kbd_events[desc_idx];
    if (ev->type == EV_KEY) {
      if (ev->code == 42 || ev->code == 54) { 
        shift_held = (ev->value != 0);        
      }
      if (ev->code == 29 || ev->code == 97) { 
        ctrl_held = (ev->value != 0);         
      }
      if (ev->value == 1) { 
        int processed = 0;
        int vibe_key = 0;
        if (ev->code == 103)
          vibe_key = 0x100; 
        else if (ev->code == 108)
          vibe_key = 0x101; 
        else if (ev->code == 105)
          vibe_key = 0x102; 
        else if (ev->code == 106)
          vibe_key = 0x103; 
        else if (ev->code == 29 || ev->code == 97)
          processed = 1; 
        else if (ev->code == 42 || ev->code == 54)
          processed = 1; 
        else if (ev->code == 28)
          vibe_key = '\n'; 
        else if (ev->code == 57)
          vibe_key = ' '; 
        else if (ev->code == 1)
          vibe_key = 27; 
        if (vibe_key) {
          if (key_callback)
            key_callback(vibe_key);
          if (gui_key_callback)
            gui_key_callback(vibe_key);
          processed = 1;
        }
        if (!processed && ev->code < 128) {
          char ascii;
          if (ctrl_held) {
            char base = keycode_to_ascii[ev->code];
            if (base >= 'a' && base <= 'z') {
              ascii = base - 'a' + 1; 
            } else if (base >= 'A' && base <= 'Z') {
              ascii = base - 'A' + 1;
            } else {
              ascii = 0; 
            }
          } else if (shift_held) {
            ascii = keycode_to_ascii_shifted[ev->code];
          } else {
            ascii = keycode_to_ascii[ev->code];
          }
          if (key_callback && ascii) {
            key_callback(ascii);
          }
          if (gui_key_callback && ascii) {
            gui_key_callback(ascii);
          }
        }
      }
    }
    uint16_t avail_idx = kbd_avail->idx % QUEUE_SIZE;
    kbd_avail->ring[avail_idx] = desc_idx;
    kbd_avail->idx++;
    kbd_last_used_idx++;
  }
  mmio_write32(kbd_base + VIRTIO_MMIO_QUEUE_NOTIFY / 4, 0);
  mmio_write32(kbd_base + VIRTIO_MMIO_INTERRUPT_ACK / 4,
               mmio_read32(kbd_base + VIRTIO_MMIO_INTERRUPT_STATUS / 4));
}

