hev_rbtree_node_prev (HevRBTreeNode *node)
{
    HevRBTreeNode *parent;
    if (hev_rbtree_node_empty (node))
        return NULL;
    if (node->left) {
        node = node->left;
        while (node->right)
            node = node->right;
        return (HevRBTreeNode *)node;
    }
    while ((parent = hev_rbtree_node_parent (node)) && node != parent->left)
        node = parent;
    return parent;
}

