static uint16_t hda_build_format(uint32_t sample_rate, uint8_t channels,
                                 uint8_t bits_per_sample) {
  struct rate_map {
    uint32_t rate;
    uint8_t base_44;
    uint8_t mult;
    uint8_t div;
  };
  static const struct rate_map rates[] = {
      {8000, 0, 1, 6},  {11025, 1, 1, 4},  {16000, 0, 1, 3}, {22050, 1, 1, 2},
      {32000, 0, 1, 2}, {44100, 1, 1, 1},  {48000, 0, 1, 1}, {88200, 1, 2, 1},
      {96000, 0, 2, 1}, {176400, 1, 4, 1}, {192000, 0, 4, 1}};
  uint8_t base_44 = 0;
  uint8_t mult = 1;
  uint8_t div = 1;
  for (size_t i = 0; i < sizeof(rates) / sizeof(rates[0]); i++) {
    if (rates[i].rate == sample_rate) {
      base_44 = rates[i].base_44;
      mult = rates[i].mult;
      div = rates[i].div;
      break;
    }
  }
  uint8_t bits_code = 1; 
  switch (bits_per_sample) {
  case 8:
    bits_code = 0;
    break;
  case 16:
    bits_code = 1;
    break;
  case 20:
    bits_code = 2;
    break;
  case 24:
    bits_code = 3;
    break;
  case 32:
    bits_code = 4;
    break;
  default:
    bits_code = 1;
    break;
  }
  if (channels == 0)
    channels = 1;
  if (channels > 16)
    channels = 16;
  uint16_t fmt = 0;
  fmt |= (base_44 ? (1 << 14) : 0);
  fmt |= ((uint16_t)(mult - 1) & 0x7) << 11;
  fmt |= ((uint16_t)(div - 1) & 0x7) << 8;
  fmt |= ((uint16_t)(channels - 1) & 0xF) << 4;
  fmt |= (uint16_t)(bits_code & 0xF);
  return fmt;
}

