static int hostapd_fill_csa_settings(struct hostapd_data *hapd,
				     struct csa_settings *settings)
{
	struct hostapd_iface *iface = hapd->iface;
	struct hostapd_freq_params old_freq;
	int ret;
	u8 chan, bandwidth;
	os_memset(&old_freq, 0, sizeof(old_freq));
	if (!iface || !iface->freq || hapd->csa_in_progress)
		return -1;
	switch (settings->freq_params.bandwidth) {
	case 80:
		if (settings->freq_params.center_freq2)
			bandwidth = CONF_OPER_CHWIDTH_80P80MHZ;
		else
			bandwidth = CONF_OPER_CHWIDTH_80MHZ;
		break;
	case 160:
		bandwidth = CONF_OPER_CHWIDTH_160MHZ;
		break;
	default:
		bandwidth = CONF_OPER_CHWIDTH_USE_HT;
		break;
	}
	if (ieee80211_freq_to_channel_ext(
		    settings->freq_params.freq,
		    settings->freq_params.sec_channel_offset,
		    bandwidth,
		    &hapd->iface->cs_oper_class,
		    &chan) == NUM_HOSTAPD_MODES) {
		wpa_printf(MSG_DEBUG,
			   "invalid frequency for channel switch (freq=%d, sec_channel_offset=%d, vht_enabled=%d, he_enabled=%d, eht_enabled=%d)",
			   settings->freq_params.freq,
			   settings->freq_params.sec_channel_offset,
			   settings->freq_params.vht_enabled,
			   settings->freq_params.he_enabled,
			   settings->freq_params.eht_enabled);
		return -1;
	}
	settings->freq_params.channel = chan;
	ret = hostapd_change_config_freq(iface->bss[0], iface->conf,
					 &settings->freq_params,
					 &old_freq);
	if (ret)
		return ret;
	ret = hostapd_build_beacon_data(hapd, &settings->beacon_after);
	hostapd_change_config_freq(iface->bss[0], iface->conf,
				   &old_freq, NULL);
	if (ret)
		return ret;
	hapd->cs_freq_params = settings->freq_params;
	hapd->cs_count = settings->cs_count;
	hapd->cs_block_tx = settings->block_tx;
	ret = hostapd_build_beacon_data(hapd, &settings->beacon_csa);
	if (ret) {
		free_beacon_data(&settings->beacon_after);
		return ret;
	}
	settings->counter_offset_beacon[0] = hapd->cs_c_off_beacon;
	settings->counter_offset_presp[0] = hapd->cs_c_off_proberesp;
	settings->counter_offset_beacon[1] = hapd->cs_c_off_ecsa_beacon;
	settings->counter_offset_presp[1] = hapd->cs_c_off_ecsa_proberesp;
	return 0;
}

void process_schedule_from_irq(void) {
  int ready_count = process_count_ready();
  if (current_pid >= 0 && ready_count <= 1) {
    return; 
  }
  if (current_pid < 0 && ready_count != 0) {
    return; 
  }
  int old_slot = current_pid;
  int start = (old_slot >= 0) ? old_slot + 1 : 0;
  for (int i = 0; i < MAX_PROCESSES; i++) {
    int idx = (start + i) % MAX_PROCESSES;
    if (proc_table[idx].state == PROC_STATE_READY) {
      if (idx != old_slot) {
        process_t *new_proc = &proc_table[idx];
        if (arch_context_get_sp(&new_proc->context) == 0 ||
            arch_context_get_pc(&new_proc->context) == 0) {
          continue; 
        }
        if (old_slot >= 0 && proc_table[old_slot].state == PROC_STATE_RUNNING) {
          proc_table[old_slot].state = PROC_STATE_READY;
        }
        proc_table[idx].state = PROC_STATE_RUNNING;
        current_pid = idx;
        current_process = new_proc;
        arch_dsb();
      }
      return;
    }
  }
}

