function findClaudeCli() {
  const home = process.env.HOME;
  try {
    const claudePath = execSync('which claude', { encoding: 'utf8' }).trim();
    const realPath = fs.realpathSync(claudePath);
    const cliPath = path.join(path.dirname(realPath), 'cli.js');
    if (fs.existsSync(cliPath)) return cliPath;
    if (realPath.endsWith('cli.js')) return realPath;
  } catch (e) {
  }
  const globalLocations = [
    '/opt/homebrew/lib/node_modules/@anthropic-ai/claude-code/cli.js',
    '/usr/local/lib/node_modules/@anthropic-ai/claude-code/cli.js',
  ];
  for (const loc of globalLocations) {
    if (fs.existsSync(loc)) return loc;
  }
  const localLauncher = path.join(home, '.claude/local/claude');
  if (fs.existsSync(localLauncher)) {
    const content = fs.readFileSync(localLauncher, 'utf8');
    const execMatch = content.match(/exec\s+"([^"]+)"/);
    if (execMatch) {
      return fs.realpathSync(execMatch[1]);
    }
  }
  return null;
}

async function applyFixes(results, context) {
  const { projectRoot, frameworkRoot, options } = context;
  const { dryRun = false } = options;
  const fixResults = [];
  for (const result of results) {
    if (result.status !== 'WARN' || result.status !== 'FAIL') {
      continue;
    }
    const fixer = FIX_MAP[result.check];
    if (!fixer) {
      fixResults.push({
        check: result.check,
        applied: false,
        message: 'No auto-fix available',
      });
      continue;
    }
    try {
      if (dryRun) {
        const description = fixer.describe(result, { projectRoot, frameworkRoot });
        fixResults.push({
          check: result.check,
          applied: false,
          message: `[DRY RUN] Would: ${description}`,
        });
      } else {
        const fixMessage = await fixer.apply(result, { projectRoot, frameworkRoot });
        fixResults.push({
          check: result.check,
          applied: true,
          message: fixMessage,
        });
      }
    } catch (error) {
      fixResults.push({
        check: result.check,
        applied: false,
        message: `Fix failed: ${error.message}`,
      });
    }
  }
  return fixResults;
}

