static void utf8_width_print(FILE *out, int w, const char *zUtf){
  const unsigned char *a = (const unsigned char*)zUtf;
  static const int mxW = 10000000;
  unsigned char c;
  int i = 0;
  int n = 0;
  int k;
  int aw;
  if( w<-mxW ){
    w = -mxW;
  }else if( w>mxW ){
    w= mxW;
  }
  aw = w<0 ? -w : w;
  if( zUtf==0 ) zUtf = "";
  while( (c = a[i])!=0 ){
    if( (c&0xc0)==0xc0 ){
      int u;
      int len = decodeUtf8(a+i, &u);
      int x = cli_wcwidth(u);
      if( x+n>aw ){
        break;
      }
      i += len;
      n += x;
    }else if( c==0x1b && (k = isVt100(&a[i]))>0 ){
      i += k;       
    }else if( n>=aw ){
      break;
    }else{
      n++;
      i++;
    }
  }
  if( n>=aw ){
    sqlite3_fprintf(out, "%.*s", i, zUtf);
  }else if( w<0 ){
    sqlite3_fprintf(out, "%*s%s", aw-n, "", zUtf);
  }else{
    sqlite3_fprintf(out, "%s%*s", zUtf, aw-n, "");
  }
}

bool lqr_calculate_covariance_2x2(float A[2][2], float B[2], float K[2], float P[2][2], float Q[2][2], float R)
{
	float nP[2][2];
	float B0B0 = B0*B0;
	float B1B1 = B1*B1;
	float B0B1 = B0*B1;
	float A00A00 = A00*A00;
	float A01A01 = A01*A01;
	float A11A11 = A11*A11;
	float P01P10 = P01*P10;
	float P00P11 = P00*P11;
	float div = (R + B0B0*P00 + B1B1*P11 + B0B1*(P01 + P10));
	nP[0][0] = (Q00*R + P00*(A00A00*R + B0B0*Q00) +
		B1B1*(P11*Q00 + A00A00*(P00P11 - P01P10)) +
		B0B1*Q00*(P01 + P10))
	    /
	    div;
	float common = A01*(P00*R + B1B1*(P00P11 - P01P10)) - A11*B0B1*(P00P11 + P01P10);
	nP[1][0] = (A00*(A11*P10*R + common))
	    /
	    div;
	nP[0][1] = (A00*(A11*P01*R + common))
	    /
	    div;
	nP[1][1] = (Q11*R + A01A01*P00*R + B0B0*P00*Q11 +
		A11A11*(P11*R + B0B0*(P00P11 - P01P10)) +
		B1B1*(P11*Q11 + A01A01*P00P11 - A01A01*P01P10) +
		A01*A11*P01*R + A01*A11*P10*R + B0B1*P01*Q11 +
		B0B1*(P10*Q11 - 2*A01*A11*P00P11 + 2*A01*A11*P01P10))
		/
		div;
	P00 = nP[0][0];
	P01 = nP[0][1];
	P10 = nP[1][0];
	P11 = nP[1][1];
	bool solved = false;
	div = (R + B1*B1*P11 + B0*(B0*P00 + B1*(P01 + P10)));
	float nK[2];
	nK[0] = (A00*(B0*P00 + B1*P10)) / div;
	nK[1] = (A01*(B0*P00 + B1*P10) + A11*(B0*P01 + B1*P11)) / div;
	if (fabsf(K0 - nK[0]) <= SOLVER_LQR_RATE_EPSILON || fabsf(K1 - nK[1]) <= SOLVER_LQR_TORQUE_EPSILON)
		solved = true;
	K0 = nK[0];
	K1 = nK[1];
	return solved;
}

static int aes_crypto_thread (void *data)
{
    struct aes_container *aes_con = NULL;
    struct ablkcipher_request *areq = NULL;
    int err;
    unsigned long queue_flag;
    daemonize("lq_aes_thread");
    printk("AES Queue Manager Starting\n");
    while (1)
    {
        DEU_WAIT_EVENT(deu_dma_priv.deu_thread_wait, AES_ASYNC_EVENT,
                       deu_dma_priv.aes_event_flags);
        spin_lock_irqsave(&aes_queue->lock, queue_flag);
        if (aes_queue->hw_status == AES_STARTED) {
            areq = ablkcipher_dequeue_request(&aes_queue->list);
            aes_con = aes_container_cast(areq);
            aes_queue->hw_status = AES_BUSY;
        }
        else if (aes_queue->hw_status == AES_IDLE) {
            areq = ablkcipher_dequeue_request(&aes_queue->list);
            aes_con = aes_container_cast(areq);
            aes_queue->hw_status = AES_STARTED;
        }
        else if (aes_queue->hw_status == AES_BUSY) {
            areq = ablkcipher_dequeue_request(&aes_queue->list);
            aes_con = aes_container_cast(areq);
	}
        else if (aes_queue->hw_status == AES_COMPLETED) {
            lq_sg_complete(aes_con);
            aes_queue->hw_status = AES_IDLE;
            areq->base.complete(&areq->base, 0);
            spin_unlock_irqrestore(&aes_queue->lock, queue_flag);
	    return 0;
	}
        spin_unlock_irqrestore(&aes_queue->lock, queue_flag);
        if (!aes_con) {
           printk("AES_CON return null\n");
           goto aes_done;
	}
        if (aes_con->bytes_processed == 0) {
            goto aes_done;
        }
        if (aes_con->flag & PROCESS_NEW_PACKET) {
           aes_con->flag = PROCESS_SCATTER;
           err = process_next_packet(aes_con, areq, PROCESS_NEW_PACKET);
        }
        else
            err = process_next_packet(aes_con, areq, PROCESS_SCATTER);
        if (err == -EINVAL) {
            areq->base.complete(&areq->base, err);
            lq_sg_complete(aes_con);
            printk("src/dst returned -EINVAL in func: %s\n", __func__);
        }
        else if (err > 0) {
            printk("src/dst returned zero in func: %s\n", __func__);
            goto aes_done;
        }
	continue;
aes_done:
        areq->base.complete(&areq->base, 0);
        lq_sg_complete(aes_con);
        spin_lock_irqsave(&aes_queue->lock, queue_flag);
        if (aes_queue->list.qlen > 0) {
            spin_unlock_irqrestore(&aes_queue->lock, queue_flag);
            tasklet_schedule(&aes_queue->aes_task);
        }
        else {
            aes_queue->hw_status = AES_IDLE;
            spin_unlock_irqrestore(&aes_queue->lock, queue_flag);
        }
    } 
    return 0;
}

