  }
  else
  {
    params.set("grid", "0");
    params.set("pv", "0");
  }
  if (dark === true)
  {
    params.set("dark", "1");
  }
  params.set("border", border.toString());
  params.set("edit", edit);
  const createHash = "#create=" + encodeURIComponent(JSON.stringify(createObj));
  const paramsStr = params.toString();
  return DRAWIO_BASE_URL + (paramsStr ? "?" + paramsStr : "") + createHash;
}

static void ford_v0_add_bit(SubGhzProtocolDecoderFordV0* instance, bool bit) {
#ifdef FORD_V0_DEBUG_BITS
    FURI_LOG_D(TAG, "Bit %d: %d", instance->bit_count, bit);
#endif
    uint32_t low = (uint32_t)instance->data_low;
    instance->data_low = (instance->data_low << 1) | (bit ? 1 : 0);
    instance->data_high = (instance->data_high << 1) | ((low >> 31) & 1);
    instance->bit_count++;
}

def _resolve_neighborhood(footprint, connectivity, ndim):


    if footprint is None:
        if connectivity is None:
            connectivity = ndim
        footprint = ndi.generate_binary_structure(ndim, connectivity)
    else:
        # Validate custom structured element
        footprint = np.asarray(footprint, dtype=bool)
        # Must specify neighbors for all dimensions
        if footprint.ndim != ndim:
            raise ValueError(
                "number of dimensions in image and footprint do not"
                "match"
            )
        # Must only specify direct neighbors
        if any(s != 3 for s in footprint.shape):
            raise ValueError("dimension size in footprint is not 3")

    return footprint

