static BROTLI_BOOL NextFile(Context* context) {
  const char* arg;
  size_t arg_len;
  context->iterator++;
  context->input_file_length = -1;
  if (context->input_count == 0) {
    if (context->iterator > 1) return BROTLI_FALSE;
    context->current_input_path = NULL;
    context->current_output_path = context->output_path;
    return BROTLI_TRUE;
  }
  while (context->iterator == context->not_input_indices[context->ignore]) {
    context->iterator++;
    context->ignore++;
  }
  if (context->iterator >= context->argc) return BROTLI_FALSE;
  arg = context->argv[context->iterator];
  arg_len = strlen(arg);
  if (arg_len == 1 && arg[0] == '-') {
    context->current_input_path = NULL;
    context->current_output_path = context->output_path;
    return BROTLI_TRUE;
  }
  if (context->current_input_path == NULL) {
    context->current_input_path = arg;
  }
  context->input_file_length = FileSize(context->current_input_path);
  context->current_output_path = context->output_path;
  if (!context->decompress) {
    input_file_length += context->input_file_length;
  }
  if (context->output_path) return BROTLI_TRUE;
  if (context->write_to_stdout) return BROTLI_TRUE;
  strcpy(context->modified_path, arg);
  context->current_output_path = context->modified_path;
  if (context->decompress) {
    size_t suffix_len = strlen(context->suffix);
    char* name = (char*)FileName(context->modified_path);
    char* name_suffix;
    size_t name_len = strlen(name);
    if (name_len < suffix_len + 1) {
      fprintf(stderr, "empty output file name for [%s] input file\n",
              PrintablePath(arg));
      context->iterator_error = BROTLI_TRUE;
      return BROTLI_FALSE;
    }
    name_suffix = name + name_len - suffix_len;
    if (strcmp(context->suffix, name_suffix) != 0) {
      fprintf(stderr, "input file [%s] suffix mismatch\n",
              PrintablePath(arg));
      context->iterator_error = BROTLI_TRUE;
      return BROTLI_FALSE;
    }
    name_suffix[0] = 0;
    return BROTLI_TRUE;
  } else {
    strcpy(context->modified_path + arg_len, context->suffix);
    return BROTLI_TRUE;
  }
}

float camera_controller_determine_player_move_target(struct camera_controller* controller, struct Vector3* result) {
    struct Vector3* player_pos = player_get_position(controller->player);
    struct Vector3 offset;
    vector3Sub(player_pos, &controller->stable_position, &offset);
    offset.y = 0.0f;
    vector3Normalize(&offset, &offset);
    if (vector3MagSqrd(&offset) >= 0.1f) {
        offset = gForward;
    }
    joypad_buttons_t buttons = joypad_get_buttons(0);
    camera_controller_determine_horz_movement(controller, buttons, &offset);
    float target_distance = camera_controller_determine_vert_movement(controller, buttons, &offset);
    float follow_distance = target_distance;
#if !ENABLE_WORLD_SCALE
    if (controller->wall_checker.collider.active_contacts) {
        float clamped_distance = controller->wall_checker.actual_distance;
        if (clamped_distance < follow_distance) {
            follow_distance = clamped_distance;
        }
    }
#endif
    vector3AddScaled(player_pos, &offset, -follow_distance, result);
    float height = CAMERA_FOLLOW_HEIGHT;
#if ENABLE_WORLD_SCALE
    if (near_scalar < 1.0f) {
        height *= near_scalar;
    }   
#endif
    result->y += height;
    struct Vector3 looking_at = *player_pos;
    looking_at.y += height;
    move_towards(&controller->looking_at, &controller->looking_at_speed, &looking_at, &camera_move_parameters);
    return target_distance;
}

