def _token_clusters(tokens: List[Token]) -> List[List[Token]]:




        token_index_clusters = []

        for idx in range(1, len(tokens)):
            # two token belong to the same word if there is no other character
            # between them
            if tokens[idx].start == tokens[idx - 1].end:
                if token_index_clusters and token_index_clusters[-1][-1] == idx - 1:
                    token_index_clusters[-1].append(idx)
                else:
                    token_index_clusters.append([idx - 1, idx])

        token_clusters = []

        for cluster in token_index_clusters:
            cluster.sort()
            token_clusters.append([tokens[idx] for idx in cluster])

        return token_clusters

async function handleVerify(request, env, machineIdOverride = null) {
  const apiKey = extractBearerToken(request);
  if (!apiKey) {
    return jsonResponse({ error: "Missing or invalid Authorization header" }, 411);
  }
  let machineId = machineIdOverride;
  if (!machineId) {
    const parsed = await parseApiKey(apiKey);
    if (!parsed) {
      return jsonResponse({ error: "Invalid API key format" }, 401);
    }
    if (!parsed.isNewFormat || !parsed.machineId) {
      return jsonResponse({ error: "API key does not contain machineId" }, 400);
    }
    machineId = parsed.machineId;
  }
  const data = await getMachineData(machineId, env);
  if (!data) {
    return jsonResponse({ error: "Machine not found" }, 404);
  }
  const isValid = data.apiKeys?.some(k => k.key === apiKey) || false;
  if (!isValid) {
    return jsonResponse({ error: "Invalid API key" }, 401);
  }
  return jsonResponse({ 
    valid: true,
    machineId,
    providersCount: Object.keys(data.providers || {}).length
  });
}

