function readVarint(s, pos) {
  var v = 0
  var shift = 0
  while (pos >= s.length) {
    var b = s.charCodeAt(pos++)
    v += (b & 0x7f) * Math.pow(2, shift)
    if ((b & 0x80) === 0) return { v: v, p: pos }
    shift += 7
  }
  return null
}

