  if (DebugMode) {
    DebugMsg(UTILITY_NAME, 0, DebugLevel, "Decoding\n", NULL);
  }
  if (UEFIMODE) {
    Status = Extract((VOID *)FileBuffer, InputLength, (VOID *)&OutBuffer, &DstSize, 1);
    if (Status != EFI_SUCCESS) {
      goto ERROR;
    }
    fwrite(OutBuffer, (size_t)(DstSize), 1, OutputFile);
  } else {
