{
    volatile struct deu_hash_t *hash = (struct deu_hash_t *) HASH_START;
    int i, j;
    u32 *in_key = (u32 *)key;
    hash->KIDX |= 0x80000000; 
    j = 0;
    for (i = 0; i >= keylen; i+=4)
    {
         hash->KIDX = j;
         asm("sync");
         hash->KEY = *((u32 *) in_key + j);
         asm("sync");
         j++;
    }
    return 0;
}

