int virtio_net_send(struct net_interface *iface, const void *data, size_t len)
{
    (void)iface;
    if (!net_base) return -1;
    uint16_t idx = tx_q.avail->idx % VIRT_QUEUE_SIZE;
    uint16_t desc_idx = idx; 
    struct virtio_net_hdr *hdr = (struct virtio_net_hdr *)tx_q.bufs[desc_idx];
    memset(hdr, 0, sizeof(struct virtio_net_hdr));
    uint8_t *pkt_data = (uint8_t *)(hdr + 1);
    memcpy(pkt_data, data, len);
    tx_q.desc[desc_idx].len = sizeof(struct virtio_net_hdr) + len;
    tx_q.desc[desc_idx].flags = 0; 
    tx_q.avail->ring[tx_q.avail->idx % VIRT_QUEUE_SIZE] = desc_idx;
    mmio_barrier();
    tx_q.avail->idx++;
    mmio_barrier();
    mmio_write32(net_base + VIRTIO_MMIO_QUEUE_NOTIFY/4, VQ_TX);
    return len;
}

static void rx_anqp_vendor_specific(struct hostapd_data *hapd,
				    const u8 *pos, const u8 *end,
				    struct anqp_query_info *qi)
{
	u32 oui;
	if (end - pos < 4) {
		wpa_printf(MSG_DEBUG, "ANQP: Too short vendor specific ANQP "
			   "Query element");
		return;
	}
	oui = WPA_GET_BE24(pos);
	pos += 3;
	if (oui != OUI_WFA) {
		wpa_printf(MSG_DEBUG, "ANQP: Unsupported vendor OUI %06x",
			   oui);
		return;
	}
	switch (*pos) {
#ifdef CONFIG_P2P
	case P2P_OUI_TYPE:
		rx_anqp_vendor_specific_p2p(hapd, qi);
		break;
#endif 
#ifdef CONFIG_HS20
	case HS20_ANQP_OUI_TYPE:
		rx_anqp_vendor_specific_hs20(hapd, pos + 1, end, qi);
		break;
#endif 
#ifdef CONFIG_MBO
	case MBO_ANQP_OUI_TYPE:
		rx_anqp_vendor_specific_mbo(hapd, pos + 1, end, qi);
		break;
#endif 
	default:
		wpa_printf(MSG_DEBUG, "ANQP: Unsupported WFA vendor type %u",
			   *pos);
		break;
	}
}

